const MODULES=[['dashboard','◫','经营驾驶舱'],['partners','♧','区域合作管理'],['agreements','▥','合作协议与授权'],['targets','◎','年度任务管理'],['colleges','▤','院校客户管理'],['programs','▣','培训项目管理'],['delivery','▦','培训交付中心'],['certificates','◇','认证与证书'],['finance','¥','费用与绩效'],['settlement','◈','认证结算中心'],['audit','≡','操作日志'],['school-admin','▥','院校管理'],['user-admin','♙','用户管理'],['permissions','▧','权限分配'],['evaluation','◈','能力评价管理'],['quality','◇','考评点核验'],['eval-home','◇','运营总览'],['eval-indicators','◇','指标体系'],['eval-masterdata','◇','主数据模型'],['eval-points','◇','考评点管理'],['eval-types','◇','题型管理'],['eval-plans','◇','命题计划'],['eval-bank','◇','试题维护'],['eval-blueprint','◇','测评蓝图'],['eval-agents','◇','专项智能体'],['eval-data','◇','数据管理'],['eval-report','◇','能力报告构建'],['eval-quality','◇','考评点核验'],['eval-practice','◇','综合测评与实训']];
const PAGES=['ecosystem-partners','agreements','delivery','settlement','partners','targets','colleges','programs','certificates','finance','audit','school-admin','user-admin','permissions'];
let role=sessionStorage.getItem('mveriRole')||'',region=sessionStorage.getItem('mveriRegion')||'R001';
let db;
try{const saved=JSON.parse(localStorage.getItem('mveriData')||'null');db=(saved&&typeof saved==='object'&&!Array.isArray(saved))?saved:structuredClone(SEED)}
catch(err){console.warn('[MVERI] Existing local data is unreadable; preserving the source in mveriData_invalidBackup',err);const raw=localStorage.getItem('mveriData');if(raw&&!localStorage.getItem('mveriData_invalidBackup'))localStorage.setItem('mveriData_invalidBackup',raw);db=structuredClone(SEED)}
for(const [key,value] of Object.entries(SEED)){if(Array.isArray(value)&&!Array.isArray(db[key]))db[key]=structuredClone(value)}
if(!Array.isArray(db.logs))db.logs=[];
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>localStorage.setItem('mveriData',JSON.stringify(db));
const log=(a)=>{db.logs.unshift({time:new Date().toLocaleString('zh-CN',{hour12:false}),role:role==='hq'?'总部':role==='region'?'区域':'院校',action:a});save()};
