const visible=r=>isHQ()||r.region===region||(role==='college'&&r.id==='C001');
const rows=k=>db[k].filter(x=>visible(x));
const nameRegion=id=>id==='HQ'?'总部直属':db.partners.find(x=>x.id===id)?.name||id;
const nameCollege=id=>db.colleges.find(x=>x.id===id)?.name||id;
const nameProgram=id=>db.programs.find(x=>x.id===id)?.name||id;
const money=v=>'¥'+Number(v||0).toLocaleString('zh-CN');
const stat=s=>`<span class="status ${/待|草稿|招生|培训|意向/.test(s)?'warn':/驳回|暂停|失效/.test(s)?'neutral':''}">${esc(s)}</span>`;
const canEdit=(k,row)=>role==='hq'?(['partners','targets','finance'].includes(k)||(k==='certificates'&&false)||(k==='colleges'&&(!row||row.region==='HQ'))):(role==='region'&&['colleges','programs','certificates'].includes(k)&&(!row||row.region===region));
// V72.23 local-only account preferences. These are NOT server credentials.
const getLocalPassword=account=>{try{return JSON.parse(localStorage.getItem('mveriDemoPasswords')||'{}')[account]||''}catch{return ''}};
const setLocalPassword=(account,password)=>{let data={};try{data=JSON.parse(localStorage.getItem('mveriDemoPasswords')||'{}')||{}}catch{}data[account]=password;localStorage.setItem('mveriDemoPasswords',JSON.stringify(data))};
const activeAccount=()=>sessionStorage.getItem('mveriActiveAccount')||(role==='hq'?'admin':role==='college'?'college01':region==='R002'?'region02':'region01');
const profileKey=()=>`mveriWorkspaceProfile:${activeAccount()}`;
const readProfile=()=>{try{return JSON.parse(localStorage.getItem(profileKey())||'{}')||{}}catch{return {}}};
const accountLabel=()=>{const p=readProfile();return String(p.displayName|| (role==='hq'?'研究院总部管理员':role==='region'?nameRegion(region):'院校协作人员'))};
const route=()=>{const h=location.hash.slice(1);const id=/^[a-z][a-z-]*$/.test(h)&&MODULES.some(m=>m[0]===h)?h:(location.pathname.split('/').pop().replace('.html','')||'dashboard');return isAllowedRoute(id)?id:'dashboard'};
function login(){
const demoAccounts=[{account:'admin',password:'123456',role:'hq',region:'R001',label:'总部管理员'},{account:'region01',password:'123456',role:'region',region:'R001',label:'华北区域负责人'},{account:'region02',password:'123456',role:'region',region:'R002',label:'华东区域负责人'},{account:'college01',password:'123456',role:'college',region:'R001',label:'院校协作人员'}];
document.body.innerHTML=`<div class="login"><div class="hero"><div class="hero-logo"><img src="../assets/mveri-logo.png" alt="现代职业教育研究院 Logo"></div><small>MVERI · NATIONAL SERVICE NETWORK</small><h1>现代职业教育研究院<br>全国区域服务协作平台</h1><p>从合作授权、年度任务，到院校拓展、培训实施、认证签发与经营考核，统一业务闭环和管理规则。</p><div class="steps"><span>01 合作授权</span><span>02 培训交付</span><span>03 评价认证</span></div></div><div class="login-right"><div class="login-card"><h2>欢迎进入工作台</h2><p class="muted">使用演示账号登录，系统自动加载对应的业务权限与示例数据。</p><form id="loginForm" autocomplete="off"><label class="field">体验角色<select id="loginRole"><option value="hq">研究院总部管理员</option><option value="region">区域服务中心负责人</option><option value="college">院校协作人员</option></select></label><label class="field" id="regionField">区域中心<select id="loginRegion"><option value="R001">华北区域服务中心</option><option value="R002">华东区域服务中心</option></select></label><label class="field">登录账号<input id="loginAccount" name="username" type="text" placeholder="请输入登录账号" required autocomplete="username"></label><label class="field">登录密码<input id="loginPassword" name="password" type="password" placeholder="请输入登录密码" required autocomplete="current-password"></label><label class="demo-option"><input id="demoFill" type="checkbox" checked> 自动填入当前角色的演示账号和密码</label><div id="demoHint" class="demo-hint"></div><div id="loginError" class="login-error" role="alert" aria-live="polite" hidden></div><button class="btn full" type="submit">登录并进入工作台 →</button></form><p class="muted mini">演示环境：账号仅用于本地体验 · 数据保存在当前浏览器 · 非真实用户认证</p></div></div></div>`;
const r=$('#loginRole'),rg=$('#loginRegion'),ac=$('#loginAccount'),pw=$('#loginPassword'),auto=$('#demoFill'),err=$('#loginError');
const chosen=()=>demoAccounts.find(x=>x.role===r.value&&(r.value!=='region'||x.region===rg.value));
function refresh(){rg.parentElement.style.display=r.value==='region'?'block':'none';let a=chosen();$('#demoHint').textContent=a?'示例账号：'+a.account+'  ·  示例密码：'+(getLocalPassword(a.account)?'已设置本机密码（请手动输入）':a.password):'';if(auto.checked&&a){ac.value=a.account;pw.value=getLocalPassword(a.account)?'':a.password}err.hidden=true}
r.onchange=refresh;rg.onchange=refresh;auto.onchange=()=>{if(auto.checked)refresh()};refresh();
$('#loginForm').onsubmit=e=>{e.preventDefault();let user=ac.value.trim(),pass=pw.value,a=demoAccounts.find(x=>x.account===user&&(getLocalPassword(x.account)||x.password)===pass&&x.role===r.value&&(x.role!=='region'||x.region===rg.value));if(!a){err.textContent='账号、密码或所选角色不匹配，请核对后重试。';err.hidden=false;return}role=a.role;region=a.region;sessionStorage.setItem('mveriRole',role);sessionStorage.setItem('mveriRegion',region);sessionStorage.setItem('mveriActiveAccount',a.account);location.href='dashboard.html'};
}
let navVisible=id=>(['school-admin','user-admin','permissions'].includes(id)?role==='hq':id.startsWith('eval-')||['evaluation','quality'].includes(id)?role==='hq':role==='hq'||(role==='region'?!['partners','agreements','audit'].includes(id):['dashboard','colleges','programs','delivery','certificates'].includes(id)));
const isAllowedRoute=(id)=> id==='journey'?role==='hq':typeof window.MVERI_UNIFIED_MENU?.allowed==='function'&&window.MVERI_UNIFIED_MENU.allowed(id,role);
const NAV_GROUPS=[['工作空间',['dashboard','journey']],['能力评价体系',['eval-home','eval-indicators','eval-masterdata','eval-points','eval-types','eval-plans','eval-bank','eval-blueprint','eval-agents','eval-data']],['合作经营',['partners','agreements','targets']],['培训业务',['colleges','programs','delivery']],['认证与结算',['certificates','settlement','finance']],['组织与授权',['school-admin','user-admin','permissions']],['系统管理',['audit']]];
const NAV_ICONS={dashboard:'▦',journey:'↗',partners:'♧',agreements:'▤',targets:'◎',colleges:'▥',programs:'▣',delivery:'▧',certificates:'◇',settlement:'◈',finance:'¥',audit:'≡','school-admin':'▥','user-admin':'♙',permissions:'▧',evaluation:'◈',quality:'◇'};
function renderNav(current){return window.MVERI_UNIFIED_MENU.render(current,role,'area')}
function setupNavAccordion(nav,current){return window.MVERI_UNIFIED_MENU.mount(nav,role,current,'area')}

const EVAL_ROUTE_MAP={'eval-home':'home','eval-indicators':'indicators','eval-masterdata':'masterdata','eval-points':'points','eval-types':'types','eval-plans':'plans','eval-bank':'bank','eval-blueprint':'blueprint','eval-agents':'agents','eval-data':'data','eval-report':null,'eval-quality':null,'eval-practice':null};
// V72.4: keep the headquarters shell mounted while the legacy assessment runtime
// is hosted once inside the content area. No navigation to a second admin shell.
const assessmentPages=new Set(Object.keys(EVAL_ROUTE_MAP).filter(id=>EVAL_ROUTE_MAP[id]));
let assessmentFrame=null, assessmentFrameLoaded=false;
function assessmentHost(){
 let host=document.getElementById('mveriAssessmentHost');
 if(!host){
  host=document.createElement('section');host.id='mveriAssessmentHost';
  host.className='mveri-assessment-host';host.hidden=true;
  document.getElementById('view').after(host);
 }
 return host;
}
function evaluationHub(){
 if(!isHQ()){console.warn('Assessment access denied');return}
 const current=window.__mveriRequestedRoute||route();if(!assessmentPages.has(current))return;
 const view=document.getElementById('view'),host=assessmentHost();
 view.hidden=true;host.hidden=false;
 const target=EVAL_ROUTE_MAP[current];
 if(!assessmentFrame){
  // The V72 legacy assessment code owns global function names; keep it isolated
  // while preserving the ONE visible headquarters shell and menu state.
  const frame=document.createElement('iframe');
  frame.id='mveriAssessmentRuntime';frame.title='能力评价业务内容';
  frame.setAttribute('loading','eager');frame.setAttribute('aria-label','能力评价业务工作区');
  frame.addEventListener('error',()=>{host.innerHTML='<div role="alert" class="panel"><h3>能力评价模块加载失败</h3><p>请检查 assessment/admin-hq.html 及相关资源是否完整部署。</p></div>';assessmentFrame=null;assessmentFrameLoaded=false});
  frame.addEventListener('load',()=>{assessmentFrameLoaded=true;const pending=frame.dataset.pendingRoute;if(pending){delete frame.dataset.pendingRoute;try{frame.contentWindow.location.hash=pending;}catch(err){console.warn(err)}}});
  frame.src='../assessment/admin-hq.html?mveri_embed=1#'+encodeURIComponent(target);
  host.append(frame);assessmentFrame=frame;
 }else if(assessmentFrameLoaded){
  try{const child=assessmentFrame.contentWindow;
   if(child.location.hash!=='#'+target)child.location.hash=target;
   else child.dispatchEvent(new child.Event('hashchange'));
  }catch(e){console.error('[MVERI] assessment bridge',e)}
 }else{
  // Loading is asynchronous; update requested route without rebuilding the iframe.
  assessmentFrame.dataset.pendingRoute=target;
 }
}
function hideAssessment(){
 const view=document.getElementById('view'),host=document.getElementById('mveriAssessmentHost');
 if(view)view.hidden=false;if(host)host.hidden=true;
}
function frame(){if(role==='hq'&&sessionStorage.getItem('mveriNavV50')!=='1'){sessionStorage.removeItem('mveriNavScroll');sessionStorage.setItem('mveriNavV50','1')}let page=route(),title=MODULES.find(x=>x[0]===page)?.[2]||'经营驾驶舱';let identity=role==='hq'?'研究院总部管理员':role==='region'?nameRegion(region):'院校协作人员';document.body.innerHTML=`<div class="shell ${role==='hq'?'workspace-hq':role==='region'?'workspace-region':'workspace-college'}"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-head"><div class="brand-logo compact"><img class="logo-full brand-mark" src="../assets/mveri-logo.png" alt="现代职业教育研究院 Logo"><img class="logo-symbol brand-mark" src="../assets/mveri-logo.png" alt="现代职业教育研究院 Logo"><div class="brand-meta single-line"><span>${role==='hq'?'总部运营平台':'全国区域服务协作平台'}</span></div></div><button type="button" class="sidebar-toggle" id="sidebarToggle" onclick="toggleSidebar()" aria-expanded="true" aria-label="收起侧边导航" title="收起侧边导航"><svg class="toggle-symbol" width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path class="panel-divider" d="M9 4v16"/><path class="collapse-chevron" d="m15 9-3 3 3 3"/></svg></button></div></div><nav class="nav" aria-label="工作台主导航">${renderNav(page)}</nav></aside><main class="main"><header class="top"><div style="display:flex;gap:12px;align-items:center"><button class="btn gray mobilemenu" onclick="document.querySelector('#sidebar').classList.toggle('open')">☰</button><div class="workspace-heading"><div class="workspace-breadcrumb">${role==='hq'?'总部运营':role==='region'?'区域服务':'院校服务'} <span>/</span> ${title}</div><h1>${title}</h1></div></div><div class="account-menu" id="workspaceAccountMenu"><button type="button" class="account-menu-trigger" id="workspaceAccountTrigger" aria-haspopup="menu" aria-expanded="false" onclick="toggleAccountMenu(event)"><span class="account-menu-avatar">${role==='hq'?'总':role==='region'?'区':'校'}</span><span class="account-menu-name" id="workspaceAccountName">${esc(accountLabel())}</span><span class="account-menu-chevron" aria-hidden="true">⌄</span></button><div class="account-menu-panel" id="workspaceAccountPanel" role="menu" hidden><div class="account-menu-summary"><strong id="workspaceAccountSummary">${esc(accountLabel())}</strong><small>${esc(activeAccount())} · ${role==='hq'?'总部管理权限':role==='region'?'区域管理权限':'院校访问权限'}</small></div><button role="menuitem" type="button" onclick="openWorkspaceProfile()">⚙ &nbsp;个人设置</button><button role="menuitem" type="button" onclick="openWorkspacePassword()">▣ &nbsp;修改密码</button><div class="account-menu-divider"></div><button role="menuitem" type="button" onclick="exitLogin()">⇥ &nbsp;退出 / 切换角色</button></div></div></header><section class="content" id="view"></section></main></div><div id="overlay"></div>`;applySidebarPreference();document.body.classList.toggle('workspace-compact',readProfile().density==='compact');render(page);const nav=document.querySelector(".nav");if(nav){setupNavAccordion(nav,page);const saved=Number(sessionStorage.getItem("mveriNavScroll")||0);nav.scrollTop=Number.isFinite(saved)?saved:0;nav.addEventListener("scroll",()=>{sessionStorage.setItem("mveriNavScroll",String(nav.scrollTop))},{passive:true});nav.querySelectorAll("a").forEach(link=>link.addEventListener("click",()=>sessionStorage.setItem("mveriNavScroll",String(nav.scrollTop))))}}

// V72.23: account menu stays in the persistent topbar, independent of page routing.
window.closeAccountMenu=()=>{const p=document.getElementById('workspaceAccountPanel'),t=document.getElementById('workspaceAccountTrigger');if(p)p.hidden=true;if(t)t.setAttribute('aria-expanded','false')};
window.toggleAccountMenu=e=>{e?.stopPropagation();const p=document.getElementById('workspaceAccountPanel'),t=document.getElementById('workspaceAccountTrigger');if(!p||!t)return;const open=p.hidden;p.hidden=!open;t.setAttribute('aria-expanded',String(open))};
document.addEventListener('click',e=>{if(!e.target.closest('#workspaceAccountMenu'))window.closeAccountMenu?.()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){window.closeAccountMenu?.();const box=document.getElementById('accountSettingsShade');if(box)box.remove()}});
function accountModal(title,content,submit){window.closeAccountMenu();document.getElementById('accountSettingsShade')?.remove();const shade=document.createElement('div');shade.className='modalshade account-settings-shade';shade.id='accountSettingsShade';shade.innerHTML=`<div class="modal account-settings-modal" role="dialog" aria-modal="true" aria-labelledby="accountSettingsTitle"><div class="account-modal-header"><h2 id="accountSettingsTitle">${esc(title)}</h2><button type="button" aria-label="关闭" class="account-close" id="accountSettingsClose">×</button></div><form id="accountSettingsForm">${content}<div class="account-settings-error" id="accountSettingsError" role="alert" hidden></div><div class="formactions"><button class="btn secondary" type="button" id="accountSettingsCancel">取消</button><button class="btn" type="submit">保存</button></div></form></div>`;document.body.append(shade);shade.querySelector('#accountSettingsClose').onclick=()=>shade.remove();shade.querySelector('#accountSettingsCancel').onclick=()=>shade.remove();shade.onclick=e=>{if(e.target===shade)shade.remove()};shade.querySelector('form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);try{submit(data);shade.remove()}catch(err){const el=shade.querySelector('#accountSettingsError');el.textContent=err.message||'保存失败';el.hidden=false}};shade.querySelector('input')?.focus()}
window.openWorkspaceProfile=()=>{const p=readProfile();accountModal('个人设置',`<p class="muted">设置当前浏览器中的工作台个人资料，不会修改其他用户的组织授权。</p><label class="field">显示名称<input name="displayName" maxlength="32" required value="${esc(p.displayName||accountLabel())}" placeholder="请输入显示名称"></label><label class="field">登录账号<input value="${esc(activeAccount())}" readonly disabled></label><label class="field">界面偏好<select name="density"><option value="comfortable" ${p.density==='comfortable'?'selected':''}>标准间距</option><option value="compact" ${p.density==='compact'?'selected':''}>紧凑间距</option></select></label><p class="account-settings-hint">当前为离线演示工程，个人设置只保存在本浏览器。</p>`,data=>{const displayName=String(data.get('displayName')||'').trim();if(displayName.length<2||displayName.length>32)throw Error('显示名称需为2至32个字符');const density=data.get('density')==='compact'?'compact':'comfortable';localStorage.setItem(profileKey(),JSON.stringify({displayName,density}));document.getElementById('workspaceAccountName').textContent=displayName;document.getElementById('workspaceAccountSummary').textContent=displayName;document.body.classList.toggle('workspace-compact',density==='compact')})};
window.openWorkspacePassword=()=>accountModal('修改密码',`<p class="muted">修改当前演示账号 <strong>${esc(activeAccount())}</strong> 的本机登录密码。</p><label class="field">原密码<input type="password" name="oldPassword" required autocomplete="current-password"></label><label class="field">新密码<input type="password" name="newPassword" required minlength="8" autocomplete="new-password" placeholder="至少8位"></label><label class="field">确认新密码<input type="password" name="confirmPassword" required minlength="8" autocomplete="new-password"></label><p class="account-settings-hint">演示密码存储在当前浏览器，不具备生产环境的安全认证能力。</p>`,data=>{const account=activeAccount(),old=String(data.get('oldPassword')||''),password=String(data.get('newPassword')||''),confirm=String(data.get('confirmPassword')||'');if(old!==(getLocalPassword(account)||'123456'))throw Error('原密码不正确');if(password.length<8)throw Error('新密码至少8位');if(password!==confirm)throw Error('两次输入的新密码不一致');if(password===old)throw Error('新密码不能与原密码相同');setLocalPassword(account,password);alert('密码已更新。下次登录请使用新密码。')});
window.exitLogin=()=>{sessionStorage.removeItem('mveriRole');sessionStorage.removeItem('mveriRegion');sessionStorage.removeItem('mveriActiveAccount');sessionStorage.removeItem('mveriNavScroll');sessionStorage.removeItem('mveri_offline_session_v3');role='';location.href='../auth/access.html'};
window.resetDemo=()=>{if(confirm('确定重置浏览器中的演示数据？所有演示修改将清除。')){localStorage.removeItem('mveriData');location.reload()}};
function banner(h,desc,buttons=''){return `<div class="intro"><div><h2>${h}</h2><div class="muted">${desc}</div></div>${buttons}</div>`}
function table(headers,items,renderRow){return `<div class="panel tablewrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${items.length?items.map(renderRow).join(''):`<tr><td colspan="${headers.length}" class="empty">当前范围暂无数据</td></tr>`}</tbody></table></div>`}
const actions=(k,r,extra='')=>`${extra}${canEdit(k,r)?`<button class="btn secondary sm" onclick="openForm('${k}','${r.id}')">编辑</button><button class="btn danger sm" onclick="removeRow('${k}','${r.id}')">删除</button>`:''}`;
function dashboard(){const ps=rows('programs'),cs=rows('colleges'),cert=rows('certificates'),t=rows('targets'),sum=ps.reduce((a,x)=>a+x.completed,0),issued=cert.filter(x=>x.status==='已签发').reduce((a,x)=>a+x.pass,0),expected=t.reduce((a,x)=>a+x.students,0),fees=rows('payments').reduce((a,x)=>a+x.amount,0);$('#view').innerHTML=banner('全国服务业务全景','合作授权 → 年度目标 → 院校拓展 → 培训实施 → 证书签发 → 经营考核')+`<div class="cards"><div class="metric"><div class="muted">${isHQ()?'区域中心数':'合作院校数'}</div><div class="value">${isHQ()?db.partners.length:cs.length}</div><div class="tag">${isHQ()?'含待审核机构':'当前授权业务范围'}</div></div><div class="metric"><div class="muted">年度培训目标</div><div class="value">${expected.toLocaleString()}</div><div class="tag">完成 ${sum} 人 · ${expected?Math.round(sum/expected*100):0}%</div></div><div class="metric"><div class="muted">认证申请 / 已签发</div><div class="value">${cert.length} / ${issued}</div><div class="tag">已签发统计仅计审核通过记录</div></div><div class="metric"><div class="muted">已核销合作款</div><div class="value">${money(fees)}</div><div class="tag">演示收款记录汇总</div></div></div><div class="panel" style="margin-bottom:18px"><h3>六阶段业务闭环</h3><div class="flowline">${[['01','区域合作','签约 / 授权'],['02','年度任务','指标 / 进度'],['03','院校开发','商机 / 客户'],['04','培训实施','班级 / 结班'],['05','认证发证','申请 / 审核'],['06','经营考核','费用 / 完成率']].map((a,i)=>`<a class="stage" href="${['partners','targets','colleges','programs','certificates','finance'][i]}.html" style="text-decoration:none;color:inherit"><b>${a[0]}</b>${a[1]}<small>${a[2]}</small></a>`).join('')}</div></div><div class="grid2"><div class="panel"><h3>年度任务达成</h3>${t.length?t.map(x=>{let actual=ps.filter(p=>p.region===x.region).reduce((n,p)=>n+p.completed,0),pct=x.students?Math.round(actual/x.students*100):0;return `<div style="margin:19px 0"><div style="display:flex;justify-content:space-between;margin-bottom:9px"><b>${nameRegion(x.region)}</b><span>${actual}/${x.students} 人</span></div><div class="bar"><span style="width:${Math.min(100,pct)}%"></span></div></div>`}).join(''):'<p class="muted">暂无年度任务记录</p>'}</div><div class="panel"><h3>待处理事项</h3><p>待审核区域合作：<b>${isHQ()?db.partners.filter(x=>x.status==='待审核').length:0}</b> 项</p><p>待总部审核认证申请：<b>${cert.filter(x=>x.status==='待总部审核').length}</b> 项</p><p>招生中培训项目：<b>${ps.filter(x=>x.status==='招生中').length}</b> 项</p><div class="notice mini">审核和签发均须满足状态条件；证书编号为演示数据。</div></div></div>`}
const schema={partners:{fields:[['name','服务中心名称','text'],['area','授权区域','text'],['owner','负责人','text'],['fee','年度合作费（元）','number'],['quota','培训指标（人）','number'],['start','有效期开始','date'],['end','有效期结束','date']],createStatus:'待审核'},targets:{fields:[['region','区域中心','region'],['year','年度','number'],['students','培训目标人数','number'],['colleges','院校目标数量','number'],['certificates','发证目标人数','number']]},colleges:{fields:[['name','院校名称','text'],['contact','联系人','text'],['phone','联系方式','text'],['status','合作状态','collegeStatus']]},programs:{fields:[['college','合作院校','college'],['name','培训项目名称','text'],['start','开始日期','date'],['end','结束日期','date'],['planned','计划人数','number'],['enrolled','报名人数','number'],['completed','结班合格人数','number'],['status','项目状态','programStatus']]},certificates:{fields:[['program','所属培训项目','program'],['count','申请人数','number'],['pass','审核通过人数','number']]},finance:{fields:[['region','区域中心','region'],['type','费用类型','text'],['amount','核销金额（元）','number'],['date','收款日期','date']]}};
function listPage(k){let add=canEdit(k)?`<button class="btn" onclick="openForm('${k}')">＋ 新建${{partners:'合作中心',targets:'年度任务',colleges:'院校客户',programs:'培训项目',certificates:'认证申请',finance:'收款记录'}[k]}</button>`:'';let info={partners:['区域授权台账','总部负责机构准入、合作费用、有效期与授权状态'],targets:['年度任务与绩效指标','总部制定指标，区域按实际培训及认证数据形成可追溯进度'],colleges:['院校客户关系','区域维护区域客户，总部仅维护直属客户；其他客户只读监管'],programs:['培训交付管理','立项、招生、培训、结班；合格人数不能超过报名人数'],certificates:['认证申请与证书签发','区域报证、总部审核、签发；审核过程保留意见与日志'],finance:['合作费用与经营分析','合作费核销、区域任务达成、培训产出分析'],audit:['操作审计','记录重要新增、修改、审核、发证操作']};let h=banner(info[k][0],info[k][1],add),rs=k==='audit'?(Array.isArray(db.logs)?db.logs:[]):rows(k==='finance'?'payments':k),tt='';switch(k){
case 'partners':tt=table(['编号','服务中心 / 授权区域','负责人','合作费 / 已收','培训指标','有效期','状态','操作'],rs,r=>`<tr><td>${r.id}</td><td><b>${esc(r.name)}</b><br><span class="muted">${esc(r.area)}</span></td><td>${esc(r.owner)}</td><td>${money(r.fee)} / ${money(r.paid)}</td><td>${r.quota}</td><td>${r.start} ~ ${r.end}</td><td>${stat(r.status)}</td><td>${r.status==='待审核'&&isHQ()?`<button class="btn sm" onclick="approvePartner('${r.id}')">批准授权</button>`:''}${actions(k,r)}</td></tr>`);break;
case 'targets':tt=table(['编号','年度','区域中心','培训目标','院校目标','发证目标','培训完成率','操作'],rs,r=>{let n=db.programs.filter(p=>p.region===r.region).reduce((n,p)=>n+p.completed,0);return `<tr><td>${r.id}</td><td>${r.year}</td><td>${nameRegion(r.region)}</td><td>${r.students}</td><td>${r.colleges}</td><td>${r.certificates}</td><td>${r.students?Math.round(n/r.students*100):0}% (${n}人)</td><td>${actions(k,r)}</td></tr>`});break;
case 'colleges':tt=table(['编号','院校名称','所属中心','联系人','联系电话','客户属性','合作状态','操作'],rs,r=>`<tr><td>${r.id}</td><td><b>${esc(r.name)}</b></td><td>${nameRegion(r.region)}</td><td>${esc(r.contact)}</td><td>${esc(r.phone)}</td><td>${r.source}</td><td>${stat(r.status)}</td><td>${actions(k,r)}</td></tr>`);break;
case 'programs':tt=table(['编号','培训项目','所属院校','所属中心','计划 / 报名 / 合格','周期','状态','操作'],rs,r=>`<tr><td>${r.id}</td><td><b>${esc(r.name)}</b></td><td>${esc(nameCollege(r.college))}</td><td>${nameRegion(r.region)}</td><td>${r.planned} / ${r.enrolled} / ${r.completed}</td><td>${r.start} ~ ${r.end}</td><td>${stat(r.status)}</td><td>${actions(k,r)}</td></tr>`);break;
case 'certificates':tt=table(['申请号','培训项目','所属中心','申请 / 核准','申请日期','审核状态','审核意见 / 编号','操作'],rs,r=>`<tr><td>${r.id}</td><td>${esc(nameProgram(r.program))}</td><td>${nameRegion(r.region)}</td><td>${r.count} / ${r.pass}</td><td>${r.date}</td><td>${stat(r.status)}</td><td>${esc(r.opinion||r.batch||'—')}</td><td>${isHQ()&&r.status==='待总部审核'?`<button class="btn sm" onclick="reviewCert('${r.id}',true)">通过并签发</button><button class="btn danger sm" onclick="reviewCert('${r.id}',false)">退回</button>`:''}${isRegion()&&r.status==='草稿'?`<button class="btn sm" onclick="submitCert('${r.id}')">提交总部审核</button>`:''}${actions(k,r)}</td></tr>`);break;
case 'finance':tt=table(['编号','所属区域','费用类型','金额','日期','核销状态','操作'],rs,r=>`<tr><td>${r.id}</td><td>${nameRegion(r.region)}</td><td>${esc(r.type)}</td><td>${money(r.amount)}</td><td>${r.date}</td><td>${stat(r.status)}</td><td>${actions(k,r)}</td></tr>`);break;
case 'audit':tt=table(['时间','身份','操作'],db.logs,r=>`<tr><td>${esc(r.time)}</td><td>${r.role}</td><td>${esc(r.action)}</td></tr>`)}
$('#view').innerHTML=h+(k==='finance'?`<div class="cards"><div class="metric"><div class="muted">已核销金额</div><div class="value">${money(rs.reduce((n,x)=>n+x.amount,0))}</div></div><div class="metric"><div class="muted">培训完成人数</div><div class="value">${rows('programs').reduce((n,x)=>n+x.completed,0)}</div></div><div class="metric"><div class="muted">签发人数</div><div class="value">${rows('certificates').filter(x=>x.status==='已签发').reduce((n,x)=>n+x.pass,0)}</div></div><div class="metric"><div class="muted">有效授权区域</div><div class="value">${db.partners.filter(x=>x.status==='有效').length}</div></div></div>`:'')+tt;}
function optionsFor(type){let a=type==='region'?db.partners.map(r=>[r.id,r.name]):type==='college'?db.colleges.filter(x=>isHQ()?x.region==='HQ':x.region===region).map(x=>[x.id,x.name]):type==='program'?db.programs.filter(x=>isHQ()?true:x.region===region).map(x=>[x.id,x.name]):type==='collegeStatus'?['意向','洽谈中','合作中','已暂停'].map(x=>[x,x]):['筹备中','招生中','培训中','已结班'].map(x=>[x,x]);return a.map(([id,n])=>`<option value="${esc(id)}">${esc(n)}</option>`).join('')}
window.openForm=(k,id='')=>{let key=k==='finance'?'payments':k,r=id?db[key].find(x=>x.id===id):null;if(id&&!canEdit(k,r)||!id&&!canEdit(k))return alert('当前角色无权修改');let fs=schema[k].fields.map(([f,label,type])=>`<label class="field">${label}${['region','college','program','collegeStatus','programStatus'].includes(type)?`<select name="${f}" ${r&&k==='certificates'?'disabled':''}>${optionsFor(type)}</select>`:`<input name="${f}" type="${type}" ${type==='number'?'min="0" step="1"':''} ${r&&k==='certificates'&&f==='pass'?'':'required'}>`}</label>`).join('');$('#overlay').innerHTML=`<div class="modalshade" onclick="closeModal(event)"><div class="modal"><h2>${id?'编辑':'新建'} · ${MODULES.find(x=>x[0]===k)?.[2]}</h2><div class="muted mini">提交后同步更新本浏览器内的业务台账及统计指标</div><form id="recordForm"><div class="formgrid">${fs}</div><div class="formactions"><button type="button" class="btn gray" onclick="closeModal()">取消</button><button class="btn" type="submit">保存</button></div></form></div></div>`;let fm=$('#recordForm');if(r)for(let el of fm.elements){if(el.name&&r[el.name]!==undefined)el.value=r[el.name]};fm.onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(fm));for(let [f,,type] of schema[k].fields)if(type==='number')v[f]=Number(v[f]);if(k==='programs'&&(v.completed>v.enrolled||v.enrolled>v.planned))return alert('数据校验：合格人数 ≤ 报名人数 ≤ 计划人数');if(k==='certificates'){let p=db.programs.find(x=>x.id===v.program);if(!p||p.status!=='已结班'||v.count>p.completed||v.pass>v.count)return alert('认证申请须关联已结班项目，且核准人数 ≤ 申请人数 ≤ 项目合格人数')}if(k==='targets'&&v.students<0)return alert('任务指标不可为负数');if(k==='partners'&&v.end<v.start)return alert('授权有效期不正确');if(k==='programs'&&v.end<v.start)return alert('培训周期不正确');if(r){Object.assign(r,v);log(`修改${k} ${id}`)}else{let prefix={partners:'R',targets:'T',colleges:'C',programs:'P',certificates:'A',finance:'F'}[k];let max=Math.max(0,...db[key].map(x=>Number(x.id.slice(1))||0));v.id=prefix+String(max+1).padStart(3,'0');v.region=(k==='partners'?v.id:isHQ()?(v.region||'HQ'):region);if(k==='colleges')v.source=isHQ()?'总部':'区域';if(k==='certificates'){v.status='草稿';v.date=new Date().toISOString().slice(0,10);v.opinion=''}if(k==='finance'){v.status='已核销';let p=db.partners.find(x=>x.id===v.region);if(p)p.paid=(p.paid||0)+v.amount}if(k==='partners'){v.status='待审核';v.paid=0}db[key].push(v);log(`新建${k} ${v.id}`)}save();$('#overlay').innerHTML='';render(route())};};
window.closeModal=e=>{if(!e||e.target.classList.contains('modalshade'))$('#overlay').innerHTML=''};
window.removeRow=(k,id)=>{let key=k==='finance'?'payments':k,r=db[key].find(x=>x.id===id);if(!r||!canEdit(k,r))return;let depend={partners:db.colleges.some(x=>x.region===id)||db.targets.some(x=>x.region===id),colleges:db.programs.some(x=>x.college===id),programs:db.certificates.some(x=>x.program===id),targets:false,certificates:r.status==='已签发',finance:false}[k];if(depend)return alert('存在下游关联业务或已签发记录，不允许直接删除');if(!confirm(`删除 ${id}？`))return;if(k==='finance'){let p=db.partners.find(x=>x.id===r.region);if(p)p.paid=Math.max(0,p.paid-r.amount)}db[key]=db[key].filter(x=>x.id!==id);log(`删除${k} ${id}`);render(route())};
window.approvePartner=id=>{let r=db.partners.find(x=>x.id===id);if(!isHQ()||r?.status!=='待审核')return;if(confirm(`批准 ${r.name} 的区域授权？`)){r.status='有效';log(`批准区域合作 ${id}`);render(route())}};
window.submitCert=id=>{let r=db.certificates.find(x=>x.id===id),p=db.programs.find(x=>x.id===r?.program);if(!isRegion()||r?.region!==region||r.status!=='草稿')return;if(!p||p.status!=='已结班'||r.count>p.completed||r.pass>r.count)return alert('请先保证培训结班及申请人数校验通过');r.status='待总部审核';log(`提交认证审核 ${id}`);render(route())};
window.reviewCert=(id,pass)=>{let r=db.certificates.find(x=>x.id===id);if(!isHQ()||r?.status!=='待总部审核')return;let opinion=prompt(pass?'请输入审核意见（签发前必填）':'请输入退回原因（必填）');if(!opinion?.trim())return;r.opinion=opinion.trim();r.status=pass?'已签发':'草稿';if(pass){r.batch='MVERI-2026-'+r.id;r.pass=r.pass||r.count}log(`${pass?'审核通过并模拟签发':'退回认证申请'} ${id}`);render(route())};
function render(page){try{if(!assessmentPages.has(page))hideAssessment();if(page==='school-admin'){renderSchoolAdmin();return}if(page==='user-admin'){renderUserAdmin();return}if(page==='permissions'){renderPermissions();return}if(page==='evaluation'||page==='quality'||page.startsWith('eval-')){evaluationHub();return}if(page==='dashboard')dashboard();else if(page==='agreements')agreementPage();else if(page==='delivery')deliveryPage();else if(page==='settlement')settlementPage();else listPage(page)}catch(error){console.error('[MVERI] 业务模块渲染失败',page,error);const view=document.getElementById('view');if(view){view.innerHTML='<section class="panel" role="alert"><h3>业务页面暂时无法显示</h3><p class="muted">模块初始化失败。请检查页面下方显示的错误说明；已保存的数据不会被自动清空。</p><pre id="moduleError" style="white-space:pre-wrap;word-break:break-word;padding:12px;background:#f5f8ff;border-radius:8px;color:#8a3015"></pre><button class="btn secondary" onclick="location.reload()">重新加载</button></section>';const diag=document.getElementById('moduleError');if(diag)diag.textContent=page+'：'+(error&&error.message?error.message:String(error));}}}

