function schoolNormalizeLevel(s){if(SCHOOL_LEVELS.includes(s?.level))return s.level;const n=String(s?.name||'');return /职业技术大学|职业大学|职业本科/.test(n)?'职教本科':/中等专业|中职|职业高中|技工学校|技师学院/.test(n)?'中职':'高职'}
