  const key=catalogKey(s),old=map.get(key)||(!s.verified?[...map.values()].find(x=>x.province===schoolNormalizeProvince(s.province,s.name)&&x.level===schoolNormalizeLevel(s)&&schoolNameKey(x.name)===schoolNameKey(s.name)&&(!x.code||!s.code||x.code===s.code)):null);
