  const candidates=same.filter(x=>(!s.province||x.province===schoolNormalizeProvince(s.province,s.name))&&(!s.level||x.level===s.level));
  const found=candidates.length===1?candidates[0]:same.length===1?same[0]:null;
  if(found){if(licensed){found.licensedId=s.id;found.license=s}else found.collegeId=s.id;return;}
  const key=catalogKey(s);const old=map.get(key);const item=old||{...s,province:schoolNormalizeProvince(s.province,s.name),level:schoolNormalizeLevel(s),directoryId:'business:'+key,verified:false,source:'原业务台账（未核验）',licensedId:'',collegeId:''};
