window.schoolCatalogImportDialog=()=>{const inp=document.createElement('input');inp.type='file';inp.accept='.csv,text/csv';inp.onchange=async()=>{const file=inp.files?.[0];if(!file)return;let text=await file.text();if(text.charCodeAt(0)===0xfeff)text=text.slice(1);const lines=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))lines.push(row);row=[];cell=''}else cell+=c}row.push(cell.trim());if(row.some(Boolean))lines.push(row);if(lines.length<2)return alert('CSV 需要表头及至少一条院校记录');const header=lines.shift().map(x=>x.replace(/\s/g,''));const find=(names)=>names.map(n=>header.indexOf(n)).find(i=>i>=0)??-1;const nameIdx=find(['院校名称','学校名称','name']),provIdx=find(['省份','所在地','province']),levelIdx=find(['办学层次','院校层次','类别','level']);if(nameIdx<0||provIdx<0||levelIdx<0)return alert('CSV 必须包含院校名称、省份、办学层次三列');const prior=schoolCatalogRead(),map=new Map(prior.map(x=>[x.name.replace(/\s+/g,''),x]));let ok=0,invalid=0;for(const r of lines){const name=String(r[nameIdx]||'').trim(),province=schoolNormalizeProvince(r[provIdx],name),level=String(r[levelIdx]||'').trim();if(!name||!SCHOOL_LEVELS.includes(level)||province==='待核实'&&String(r[provIdx]||'').trim()!=='待核实'){invalid++;continue}map.set(name.replace(/\s+/g,''),{name,province,level,source:'全国目录'});ok++}if(!ok)return alert('没有有效记录。层次仅支持：职教本科、高职、中职；省份须使用规范名称。');localStorage.setItem(SCHOOL_CATALOG_KEY,JSON.stringify([...map.values()]));schoolTreeKeyword='';schoolTreeSelected='level:职教本科';renderSchoolAdmin();alert(`成功读取 ${ok} 条院校记录；无效 ${invalid} 条。相同院校名称已更新，原席位和账号未修改。`)};inp.click()};

window.schoolSelect=id=>{schoolSelected=id;renderSchoolAdmin();document.querySelector('#schoolDetails')?.scrollIntoView({behavior:'smooth',block:'start'})};
window.schoolOpenSchool=(id,prefillName='')=>{if(!isHQ())return;const api=window.MVERI_SCHOOL_LICENSE,d=api.get(),s=d.schools.find(x=>x.id===id),regionOpts=[['R001','华北区域服务中心'],['R002','华东区域服务中心'],['R003','华中区域服务中心'],['HQ','总部直属']];let collegeOpts=[['NONE','不关联现有业务客户'],...db.colleges.map(x=>[x.id,x.name])];modalV2(id?'编辑院校及席位':'新增入驻院校',[{key:'name',label:'院校名称',type:'text',value:s?.name||prefillName||''},{key:'level',label:'办学层次',options:SCHOOL_LEVELS.map(v=>[v,v])},{key:'province',label:'所在省份',options:SCHOOL_PROVINCES.map(v=>[v,v])},{key:'region',label:'所属区域',options:regionOpts.map(([v,l])=>[v,l])},{key:'collegeId',label:'关联现有院校客户',options:collegeOpts},{key:'contact',label:'联系人',type:'text',value:s?.contact||'',required:false},{key:'phone',label:'联系方式',type:'text',value:s?.phone||'',required:false},{key:'seats',label:'授权席位数',type:'number',value:s?.seats||5,min:1},{key:'status',label:'院校状态',options:[['启用','启用'],['停用','停用']]}],o=>{const sid=api.saveSchool(o,id);schoolSelected=sid;schoolTreeSelected='school:'+(schoolDirectory().find(x=>x.licensedId===sid)?.directoryId||o.name);log((id?'更新':'新增')+'院校席位授权 '+sid+' · '+o.seats+'席');renderSchoolAdmin()},'席位数不得小于已有启用账号数量；已停用院校不允许登录。');const form=$('#v2form');if(form&&s){form.elements.level.value=schoolNormalizeLevel(s);form.elements.province.value=schoolNormalizeProvince(s.province,s.name);form.elements.region.value=s.region;form.elements.collegeId.value=s.collegeId||'NONE';form.elements.status.value=s.status}else if(form&&prefillName){const found=schoolDirectory().find(x=>'school:'+x.directoryId===schoolTreeSelected)||schoolDirectory().find(x=>x.name===prefillName);if(found){form.elements.level.value=found.level;form.elements.province.value=found.province}}};
window.schoolOpenUser=id=>{if(!isHQ())return;const api=window.MVERI_SCHOOL_LICENSE,d=api.get(),u=d.users.find(x=>x.id===id),schoolId=u?.school||schoolSelected;if(!schoolId)return alert('请先选择院校');modalV2(id?'编辑院校账号':'开通院校账号',[{key:'school',label:'所属院校',options:d.schools.map(s=>[s.id,s.name])},{key:'account',label:'登录账号（4～32位）',type:'text',value:u?.account||''},{key:'name',label:'真实姓名',type:'text',value:u?.name||''},{key:'type',label:'账号类型',options:[['管理员','管理员'],['普通用户','普通用户']]},{key:'status',label:'账号状态',options:[['启用','启用（占用席位）'],['停用','停用（释放席位）']]},{key:'password',label:id?'新密码（留空不修改）':'初始登录密码（至少6位）',type:'text',value:'',required:!id}],o=>{const uid=api.saveUser(o,id);schoolSelected=o.school;log((id?'编辑':'开通')+'院校用户 '+uid+' · '+o.account);renderSchoolAdmin()},'正式系统应由后端生成一次性初始口令，不应长期明文保存密码。');const form=$('#v2form');if(form){form.elements.school.value=schoolId;form.elements.type.value=u?.type||'普通用户';form.elements.status.value=u?.status||'启用'}};
window.schoolToggleUser=id=>{if(!isHQ())return;const api=window.MVERI_SCHOOL_LICENSE,u=api.get().users.find(x=>x.id===id);if(!u)return;try{api.setUserStatus(id,u.status==='启用'?'停用':'启用');log('院校账号 '+u.account+' 状态修改');renderSchoolAdmin()}catch(e){alert(e.message)}};
window.schoolResetUser=id=>{const api=window.MVERI_SCHOOL_LICENSE,u=api.get().users.find(x=>x.id===id);if(!u)return;const value=prompt('请为 '+u.account+' 设置新的初始密码（至少6位）：');if(value===null)return;try{api.saveUser({...u,password:value},id);log('重置院校用户 '+u.account+' 的初始密码');renderSchoolAdmin();alert('初始密码已更新')}catch(e){alert(e.message)}};

/* V59 unified user admin. Schools are managed by V58 license API, so seats cannot be bypassed. */
let userFilterGroup='all',userFilterTerm='',userFilterStatus='all',userFilterUnit='all',userPage=1,userPageSize=20,userFocus='',userSelection=new Set();
const USER_REGION_NAMES={'R001':'华北区域服务中心','R002':'华东区域服务中心','R003':'华中区域服务中心',HQ:'研究院总部'};
const USER_GROUP_NAMES={hq:'研究院用户',school:'院校用户',region:'区域中心用户',personal:'个人注册用户'};
function userDirectoryContext(){const all=window.MVERI_USERS.all(),lic=window.MVERI_SCHOOL_LICENSE.get();const schoolMap=new Map(lic.schools.map(x=>[x.id,x]));const organization=u=>u.group==='school'?(schoolMap.get(u.unit)?.name||u.unit||'未关联院校'):u.group==='personal'?(schoolMap.get(u.unit)?.name||(u.unit==='independent'?'独立个人注册':u.unit||'未关联机构')):(USER_REGION_NAMES[u.unit]||u.unit||'未关联组织');const filtered=all.filter(u=>(userFilterGroup==='all'||u.group===userFilterGroup)&&(userFilterStatus==='all'||u.status===userFilterStatus)&&(userFilterUnit==='all'||u.unit===userFilterUnit)&&(!userFilterTerm||[u.account,u.name,u.role,u.unit,organization(u),u.sourceLabel,u.createdAt].join(' ').toLowerCase().includes(userFilterTerm.toLowerCase())));return {all,lic,schoolMap,organization,filtered};}
function userH(v){return esc(String(v??''))}
function userSafeId(v){return String(v??'').replace(/[^\w-]/g,'')}
function renderUserAdmin(){
 if(!isHQ()){$('#view').innerHTML='<section class="panel">仅研究院总部有权管理用户</section>';return}
 const {all,lic,schoolMap,organization,filtered}=userDirectoryContext();
 const groups=[['all','全部用户'],['hq','研究院用户'],['school','院校用户 / 教师'],['region','区域服务中心'],['personal','个人注册用户']];
 const totalPage=Math.max(1,Math.ceil(filtered.length/userPageSize));userPage=Math.min(Math.max(1,userPage),totalPage);
 const rows=filtered.slice((userPage-1)*userPageSize,userPage*userPageSize);const focused=all.find(u=>u.id===userFocus&&u.group!=='');
 const units=[...new Map(all.map(u=>[u.unit,organization(u)]).filter(x=>x[0]).map(x=>[x[0],x])).values()].sort((a,b)=>a[1].localeCompare(b[1],'zh-CN'));
 const remaining=filtered.length?`${(userPage-1)*userPageSize+1}–${Math.min(userPage*userPageSize,filtered.length)}`:'0';
 const active=all.filter(u=>u.status==='启用').length;const selected=filtered.filter(u=>userSelection.has(u.group+'::'+u.id)&&u.group!=='personal');
 const cards=[['全部用户',all.length,'统一账号目录'],['启用账号',active,'不等于已占席位'],['院校账号',all.filter(u=>u.group==='school').length,'占用席位由授权台账计算'],['个人注册',all.filter(u=>u.group==='personal').length,'独立注册，不占院校席位']];
 const detail=focused?`<div class="user-detail-title"><span class="user-avatar">${userH((focused.name||focused.account||'用').slice(0,1))}</span><div><h3>${userH(focused.name||'未填写姓名')}</h3><p>${userH(focused.account)}</p></div><span class="user-state ${focused.status==='启用'?'enabled':'disabled'}">${userH(focused.status)}</span></div><dl class="user-detail-fields">${[['用户编号',focused.id],['用户身份',USER_GROUP_NAMES[focused.group]||focused.group],['所属组织',organization(focused)],['岗位角色',focused.role],['注册或创建时间',focused.createdAt||'历史数据未记录'],['数据来源',focused.sourceLabel||'平台账号台账'],['席位规则',focused.group==='school'?(focused.status==='启用'?'占用 1 席':'停用不占席'):'不计入院校席位']].map(([a,b])=>`<div><dt>${userH(a)}</dt><dd>${userH(b)}</dd></div>`).join('')}</dl><div class="user-detail-actions">${focused.group==='personal'?`<button class="btn secondary" onclick="userPersonalDetail('${userSafeId(focused.id)}')">查看注册档案</button>`:`<button class="btn" onclick="userOpen('${userSafeId(focused.id)}','${focused.group}')">编辑用户</button>`}<button class="btn secondary" onclick="userToggle('${userSafeId(focused.id)}','${focused.group}')">${focused.status==='启用'?'停用账号':'启用账号'}</button><button class="btn gray" onclick="userReset('${userSafeId(focused.id)}','${focused.group}')">重设密码</button></div>`:`<div class="user-detail-empty"><span>◉</span><strong>选择一名用户</strong><p>在中间列表点击姓名，可查看身份、组织、席位和账号操作。</p></div>`;
 $('#view').innerHTML=`<div class="intro user-admin-intro"><div><h2>用户管理</h2><p class="muted">统一账号目录 · 组织归属 · 席位关联 · 生命周期管理</p></div><div class="user-top-actions"><a class="btn secondary" href="permissions.html" data-route="permissions">权限分配</a><button type="button" class="btn secondary" onclick="userExportCsv()">导出当前结果</button><button class="btn" onclick="userOpen()">＋ 开通用户</button></div></div>
 <section class="user-overview">${cards.map(([title,value,desc])=>`<div class="user-kpi"><span>${title}</span><strong>${value.toLocaleString('zh-CN')}</strong><small>${desc}</small></div>`).join('')}</section>
 <div class="user-workspace"><aside class="user-groups"><div class="user-section-heading">用户分类 <span>按身份</span></div>${groups.map(([g,label])=>`<button type="button" class="user-group-item ${userFilterGroup===g?'active':''}" onclick="userChoose('${g}')"><span>${label}</span><b>${g==='all'?all.length:all.filter(u=>u.group===g).length}</b></button>`).join('')}<div class="user-group-foot">院校账号的启停和新增仍经过原授权席位接口校验。</div></aside>
 <section class="user-results"><div class="user-results-top"><div><h3>用户目录</h3><p>支持组合筛选、分页查看和批量启停。</p></div><span class="user-count">匹配 ${filtered.length} 人</span></div>
 <form id="userFilterForm" class="user-filter-panel"><label class="user-search-box"><span>搜索</span><input id="userQuery" value="${userH(userFilterTerm)}" placeholder="账号 / 姓名 / 岗位 / 组织"></label><label>账号状态<select id="userStatus">${[['all','全部状态'],['启用','启用'],['停用','停用']].map(([v,t])=>`<option value="${v}" ${userFilterStatus===v?'selected':''}>${t}</option>`).join('')}</select></label><label>所属组织<select id="userUnit"><option value="all">全部组织</option>${units.map(([v,label])=>`<option value="${userH(v)}" ${userFilterUnit===v?'selected':''}>${userH(label)}</option>`).join('')}</select></label><button class="btn" type="submit">查询</button><button class="btn secondary" type="button" onclick="userClearFilters()">重置</button></form>
 <div class="user-batch-toolbar"><label><input type="checkbox" id="userSelectPage" ${rows.filter(u=>u.group!=='personal').length&&rows.filter(u=>u.group!=='personal').every(u=>userSelection.has(u.group+'::'+u.id))?'checked':''}> 本页可管理账号</label><span>已选 ${selected.length} 项</span><button class="btn secondary sm" ${selected.length?'':'disabled'} onclick="userBatchStatus('启用')">批量启用</button><button class="btn secondary sm" ${selected.length?'':'disabled'} onclick="userBatchStatus('停用')">批量停用</button><button class="btn gray sm" onclick="userSelection.clear();renderUserAdmin()">清空选择</button></div>
 <div class="user-table-scroll"><table class="user-table"><thead><tr><th>选择</th><th>账号 / 姓名</th><th>身份类型</th><th>所属组织</th><th>岗位角色</th><th>席位</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(u=>{const key=u.group+'::'+u.id;return `<tr class="${userFocus===u.id?'selected':''}"><td>${u.group==='personal'?'<span title="个人注册账号不支持批量操作">—</span>':`<input type="checkbox" class="user-row-select" data-key="${userH(key)}" ${userSelection.has(key)?'checked':''}>`}</td><td><button class="user-name-link" onclick="userFocusRow('${userSafeId(u.id)}')"><strong>${userH(u.name||'未填写姓名')}</strong><small>${userH(u.account)}</small></button></td><td><span class="user-group-pill">${userH(USER_GROUP_NAMES[u.group]||u.group)}</span></td><td title="${userH(organization(u))}">${userH(organization(u))}</td><td>${userH(u.role)}</td><td>${u.group==='school'?(u.status==='启用'?'1 席':'0 席'):'—'}</td><td><span class="user-state ${u.status==='启用'?'enabled':'disabled'}">${userH(u.status)}</span></td><td><button class="user-view-link" onclick="userFocusRow('${userSafeId(u.id)}')">查看详情</button></td></tr>`}).join('')||'<tr><td colspan="8" class="user-no-results">当前条件下没有匹配用户，请调整筛选条件。</td></tr>'}</tbody></table></div>
 <footer class="user-pager"><span>显示 ${remaining} / ${filtered.length} 条</span><div><label>每页 <select id="userPageSize">${[10,20,50,100].map(n=>`<option value="${n}" ${n===userPageSize?'selected':''}>${n}</option>`).join('')}</select> 条</label><button type="button" ${userPage===1?'disabled':''} onclick="userGoPage(${userPage-1})">上一页</button><b>${userPage} / ${totalPage}</b><button type="button" ${userPage>=totalPage?'disabled':''} onclick="userGoPage(${userPage+1})">下一页</button></div></footer></section>
 <aside class="user-detail"><div class="user-section-heading">账号详情 <span>快捷操作</span></div>${detail}</aside></div>
 <p class="school-disclaimer">账号信息保留在原有数据源中；个人注册账号不占院校席位。批量启停仅作用于显式选中的管理账号，并逐条执行原权限及席位校验。正式部署仍须引入服务端认证与审计。</p>`;
 document.querySelector('#userFilterForm')?.addEventListener('submit',e=>{e.preventDefault();userFilterTerm=document.getElementById('userQuery').value.trim();userFilterStatus=document.getElementById('userStatus').value;userFilterUnit=document.getElementById('userUnit').value;userPage=1;userSelection.clear();renderUserAdmin()});
 document.querySelector('#userSelectPage')?.addEventListener('change',e=>{for(const u of rows.filter(x=>x.group!=='personal')){const key=u.group+'::'+u.id;if(e.target.checked)userSelection.add(key);else userSelection.delete(key)}renderUserAdmin()});
 document.querySelectorAll('.user-row-select').forEach(c=>c.addEventListener('change',e=>{if(e.target.checked)userSelection.add(c.dataset.key);else userSelection.delete(c.dataset.key);renderUserAdmin()}));
 document.querySelector('#userPageSize')?.addEventListener('change',e=>{userPageSize=+e.target.value;userPage=1;renderUserAdmin()});
}
window.userChoose=g=>{userFilterGroup=g;userPage=1;userSelection.clear();renderUserAdmin()};
window.userClearFilters=()=>{userFilterTerm='';userFilterStatus='all';userFilterUnit='all';userPage=1;userSelection.clear();renderUserAdmin()};
window.userGoPage=n=>{userPage=n;renderUserAdmin()};
window.userFocusRow=id=>{userFocus=id;renderUserAdmin()};
window.userExportCsv=()=>{const {filtered,organization}=userDirectoryContext();const lines=[['账号','姓名','身份','所属组织','岗位角色','账号状态','席位占用','创建时间'],...filtered.map(u=>[u.account,u.name,USER_GROUP_NAMES[u.group]||u.group,organization(u),u.role,u.status,u.group==='school'&&u.status==='启用'?'1':'0',u.createdAt||''])];const csv='\ufeff'+lines.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MVERI_用户目录_'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.userBatchStatus=target=>{if(!isHQ())return;const {filtered}=userDirectoryContext(),choices=filtered.filter(u=>u.group!=='personal'&&userSelection.has(u.group+'::'+u.id)&&u.status!==target);if(!choices.length)return alert('没有需要变更状态的选中账号');if(!confirm(`确认将 ${choices.length} 个账号批量${target==='启用'?'启用':'停用'}？院校账号仍受席位限制。`))return;const errors=[];let success=0;for(const u of choices){try{if(u.group==='school')window.MVERI_SCHOOL_LICENSE.setUserStatus(u.id,target);else window.MVERI_USERS.toggle(u.id);log(`批量${target}账号 ${u.account}`);success++}catch(e){errors.push(`${u.account}：${e.message}`)}}userSelection.clear();renderUserAdmin();alert(`成功 ${success} 个，失败 ${errors.length} 个。`+(errors.length?'\n'+errors.slice(0,10).join('\n'):''))};
window.userPersonalDetail=id=>{if(!isHQ())return;const u=window.MVERI_USERS.all().find(x=>x.id===id&&x.group==='personal');if(!u)return alert('用户不存在');const lic=window.MVERI_SCHOOL_LICENSE.get();const school=lic.schools.find(x=>x.id===u.unit);const info=[['账号',u.account],['姓名',u.name],['注册来源',u.sourceLabel||'公共服务平台个人注册'],['注册时间',u.createdAt||'历史记录未记录'],['关联院校',school?.name||'独立个人用户'],['关联个人档案',u.person||'暂无'],['账号状态',u.status||'启用'],['席位计费','不占用院校后台席位']];const html='<div class="panel" style="margin:0"><h3>注册用户档案</h3>'+info.map(([k,v])=>'<div style="display:flex;justify-content:space-between;padding:10px;border-bottom:1px solid #e7edf8;gap:16px"><span class="muted">'+esc(k)+'</span><strong>'+esc(v)+'</strong></div>').join('')+'<p class="muted mini">个人学习记录保存在个人服务端原有业务数据中；总部当前仅显示身份索引，不推断不存在的测评或培训记录。</p></div>';const shade=document.createElement('div');shade.className='modalshade';shade.innerHTML='<div class="modal" role="dialog" aria-modal="true"><button class="btn gray sm" type="button" style="float:right" id="regClose">关闭</button>'+html+'</div>';document.body.append(shade);shade.querySelector('#regClose').onclick=()=>shade.remove();shade.addEventListener('click',e=>{if(e.target===shade)shade.remove()})};
window.userOpen=(id='',group='')=>{
 if(!isHQ())return;const license=window.MVERI_SCHOOL_LICENSE,db=license.get();let user=window.MVERI_USERS.all().find(x=>x.id===id&&x.group===group);
 const initialGroup=user?.group||group|| (['all','personal'].includes(userFilterGroup)?'school':userFilterGroup);
 const fieldGroup=id?[]:[{...F('group','用户类型'),options:[['hq','研究院用户'],['school','院校用户（含教师）'],['region','区域服务中心用户']]}];
 const data={group:initialGroup,unit:user?.unit||'',name:user?.name||'',account:user?.account||'',role:user?.role||'',status:user?.status||'启用',password:''};
 const fields=[...fieldGroup,{...F('unit','所属组织'),options:[['HQ','研究院总部'],...db.schools.map(x=>[x.id,x.name]),['R001','华北区域服务中心'],['R002','华东区域服务中心'],['R003','华中区域服务中心']]},F('name','姓名'),F('account','登录账号'),{...F('role','岗位角色'),options:[['平台管理员','平台管理员'],['标准管理员','标准管理员'],['认证审核员','认证审核员'],['运营人员','运营人员'],['管理员','院校管理员'],['教师','教师'],['普通用户','院校普通用户'],['区域负责人','区域负责人'],['项目经理','区域项目经理'],['区域业务人员','区域业务人员']]},{...F('status','账号状态'),options:[['启用','启用'],['停用','停用']]},{...F('password',id?'新密码（留空不修改）':'初始密码','text'),required:!id}];
 // modalV2 validates input in save callback; role/group field allowed only on new users
 modalV2(id?'编辑用户':'开通用户',fields,o=>{
  const g=id?data.group:o.group,unit=o.unit;
  if((g==='school'&&!db.schools.some(x=>x.id===unit))||(g==='hq'&&unit!=='HQ')||(g==='region'&&!['R001','R002','R003'].includes(unit)))throw Error('所选组织与用户类型不匹配');
  if(g==='school'){
   if(!['管理员','教师','普通用户'].includes(o.role))throw Error('院校用户角色只能为管理员、教师、普通用户');
   license.saveUser({school:unit,name:o.name,account:o.account,type:o.role,status:o.status,password:o.password},id||undefined);
  }else{
   window.MVERI_USERS.save({group:g,unit,name:o.name,account:o.account,role:o.role,status:o.status,password:o.password},id||undefined);
  }
  log('用户管理：'+o.account+' / '+g);renderUserAdmin();
 },'院校账号占用授权席位；总部与区域账号不占院校席位。');
 const form=$('#v2form');if(!form)return;
 // select correct values; enforce filtered organization & roles through visible form, not only save checks
 const field=k=>form.querySelector('[name="'+k+'"]');
 if(field('group'))field('group').value=initialGroup;
 for(const [key,val] of Object.entries(data)){if(field(key)&&val)field(key).value=val}
 const sync=()=>{const g=id?initialGroup:field('group')?.value||initialGroup;
  const allowed=g==='school'?['管理员','教师','普通用户']:g==='region'?['区域负责人','项目经理','区域业务人员']:['平台管理员','标准管理员','认证审核员','运营人员'];
  const allowedUnits=g==='school'?db.schools.map(x=>x.id):g==='region'?['R001','R002','R003']:['HQ'];
  const roleEl=field('role'),unitEl=field('unit');
  for(const o of roleEl.options)o.hidden=!allowed.includes(o.value);
  for(const o of unitEl.options)o.hidden=!allowedUnits.includes(o.value);
  if(!allowed.includes(roleEl.value))roleEl.value=allowed[0];
  if(!allowedUnits.includes(unitEl.value))unitEl.value=allowedUnits[0]||'';
 };
 field('group')?.addEventListener('change',sync);sync();
};
window.userToggle=(id,g)=>{if(!isHQ())return;try{if(g==='personal'){window.MVERI_REGISTERED.setStatus(id,window.MVERI_REGISTERED.get().find(x=>x.account===id)?.status==='停用'?'启用':'停用')}else if(g==='school'){const api=window.MVERI_SCHOOL_LICENSE,u=api.get().users.find(x=>x.id===id);api.setUserStatus(id,u.status==='启用'?'停用':'启用')}else window.MVERI_USERS.toggle(id);log('用户状态调整 '+id);renderUserAdmin()}catch(e){alert(e.message)}};
window.userReset=(id,g)=>{if(!isHQ())return;const v=prompt('请输入新密码（至少8位）');if(v===null)return;if(v.length<(g==='personal'?8:6))return alert('密码长度不足');try{if(g==='personal'){window.MVERI_REGISTERED.resetPassword(id,v)}else if(g==='school'){const api=window.MVERI_SCHOOL_LICENSE,u=api.get().users.find(x=>x.id===id);api.saveUser({...u,password:v},id)}else{const u=window.MVERI_USERS.get().users.find(x=>x.id===id);window.MVERI_USERS.save({...u,password:v},id)}log('用户密码重设 '+id);renderUserAdmin()}catch(e){alert(e.message)}};

function initV2(){let init={agreements:[{id:'G001',region:'R001',number:'MVERI-COOP-2026-001',model:'省级非独家',sign:'2026-01-01',start:'2026-01-01',end:'2026-12-31',amount:120000,first:60000,second:60000,stage:'生效',memo:'年度培训目标1500人；考核按结班及发证独立统计'},{id:'G002',region:'R002',number:'MVERI-COOP-2026-002',model:'省级非独家',sign:'2026-03-01',start:'2026-03-01',end:'2027-02-28',amount:150000,first:90000,second:60000,stage:'生效',memo:'年度培训目标2000人'}],opportunities:[{id:'O001',region:'R001',college:'C001',name:'教师素智能力提升项目',contact:'张老师',value:88000,stage:'已签约',follow:'2026-09-02',note:'已转入培训项目P001'},{id:'O002',region:'R001',college:'C002',name:'AI教学能力培训',contact:'刘老师',value:68000,stage:'谈判中',follow:'2026-10-29',note:'确认培训人数与开班时间'},{id:'O003',region:'R002',college:'C003',name:'师资认证专项班',contact:'周老师',value:105000,stage:'已签约',follow:'2026-09-28',note:'已转入P003'}],batches:[{id:'B001',region:'R001',program:'P001',coach:'李老师',course:'教师素智素养核心模块',required:32,delivered:32,attendance:96,assessment:88,docs:'课表、签到、测评汇总、结班记录',status:'已结班'},{id:'B002',region:'R001',program:'P002',coach:'孙老师',course:'AI教学能力与应用',required:24,delivered:0,attendance:0,assessment:0,docs:'',status:'筹备中'},{id:'B003',region:'R002',program:'P003',coach:'吴老师',course:'数智能力认证培训',required:40,delivered:27,attendance:90,assessment:0,docs:'课表、阶段签到',status:'培训中'}],learners:[{id:'L001',region:'R001',batch:'B001',name:'张明',code:'DEMO-001',hours:32,score:92,status:'合格'},{id:'L002',region:'R001',batch:'B001',name:'李华',code:'DEMO-002',hours:30,score:81,status:'合格'},{id:'L003',region:'R001',batch:'B001',name:'王颖',code:'DEMO-003',hours:24,score:66,status:'未合格'},{id:'L004',region:'R002',batch:'B003',name:'赵洁',code:'DEMO-004',hours:26,score:0,status:'学习中'}],settlements:[{id:'S001',region:'R001',application:'A001',unit:160,quantity:146,amount:23360,paid:0,status:'待确认',date:'2026-10-22'}],certRecords:[],paymentPlans:[{id:'I001',region:'R001',agreement:'G001',label:'首期',due:'2026-01-15',amount:60000,paid:60000},{id:'I002',region:'R001',agreement:'G001',label:'尾期',due:'2026-07-01',amount:60000,paid:60000},{id:'I003',region:'R002',agreement:'G002',label:'首期',due:'2026-03-20',amount:90000,paid:90000},{id:'I004',region:'R002',agreement:'G002',label:'尾期',due:'2026-11-30',amount:60000,paid:0}]};for(let [key,val] of Object.entries(init))if(!Array.isArray(db[key]))db[key]=structuredClone(val);save()}
const uid=(k,p)=>p+String(Math.max(0,...db[k].map(x=>Number(x.id.replace(/\D/g,''))||0))+1).padStart(3,'0');
const owns=(r)=>isHQ()||r.region===region;
const moneyText=n=>money(n);
function modalV2(title,fields,onSave,notice=''){let h=`<div class="modalshade" onclick="closeModal(event)"><div class="modal"><h2>${esc(title)}</h2><p class="muted mini">${esc(notice)}</p><form id="v2form"><div class="formgrid">${fields.map(f=>`<label class="field">${esc(f.label)}${f.options?`<select name="${f.key}" required>${f.options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${f.key}" rows="3" ${f.required===false?'':'required'}>${esc(f.value||'')}</textarea>`:`<input name="${f.key}" type="${f.type||'text'}" value="${esc(f.value??'')}" ${f.min!==undefined?`min="${f.min}"`:''} ${f.required===false?'':'required'}>`}</label>`).join('')}</div><div class="formactions"><button type="button" class="btn gray" onclick="closeModal()">取消</button><button class="btn" type="submit">保存并流转</button></div></form></div></div>`;$('#overlay').innerHTML=h;$('#v2form').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.currentTarget));try{let result=onSave(o);if(result===false)return;save();$('#overlay').innerHTML='';render(route())}catch(err){alert(err.message)}}}
const F=(key,label,type='text',value='',opts=null)=>({key,label,type,value,options:opts});
const regionOpts=()=>db.partners.map(r=>[r.id,r.name]);
const collegeOpts=()=>db.colleges.filter(r=>!isRegion()||r.region===region).map(r=>[r.id,r.name]);
const programOpts=()=>db.programs.filter(r=>owns(r)).map(r=>[r.id,r.name]);
function agreementPage(){let rr=db.agreements.filter(owns),pi=db.paymentPlans.filter(owns),p=db.partners;$('#view').innerHTML=banner('区域合作经营体系','合作申请 → 审批签约 → 授权生效 → 分期收款 → 年度考核 → 续约退出',isHQ()?'<button class="btn" onclick="addAgreement()">＋ 新建合作协议</button>':'')+`<div class="cards"><div class="metric"><div class="muted">有效协议</div><div class="value">${rr.filter(x=>x.stage==='生效').length}</div></div><div class="metric"><div class="muted">协议金额</div><div class="value">${moneyText(rr.reduce((t,x)=>t+x.amount,0))}</div></div><div class="metric"><div class="muted">计划应收</div><div class="value">${moneyText(pi.reduce((t,x)=>t+x.amount-x.paid,0))}</div></div><div class="metric"><div class="muted">待批准中心</div><div class="value">${p.filter(x=>x.status==='待审核').length}</div></div></div><div class="panel"><h3>合作授权与协议台账</h3><div class="notice mini">区域授权仅由总部批准。协议状态与机构授权台账分开管理；付款不自动替代授权审批。</div></div>`+table(['协议号','区域中心','合作模式','签约/有效期','合同金额','协议状态','操作'],rr,r=>`<tr><td><b>${esc(r.number)}</b></td><td>${nameRegion(r.region)}</td><td>${esc(r.model)}</td><td>${r.sign}<br>${r.start} ~ ${r.end}</td><td>${moneyText(r.amount)}</td><td>${stat(r.stage)}</td><td>${isHQ()?`<button class="btn sm secondary" onclick="changeAgreement('${r.id}')">变更状态</button>`:'—'}</td></tr>`)+`<div class="intro" style="margin-top:24px"><h2>合同分期应收与核销</h2>${isHQ()?'<button class="btn" onclick="addInstallment()">＋ 新建分期</button>':''}</div>`+table(['分期编号','协议','所属中心','期次','到期日期','应收','已核销','剩余','操作'],pi,r=>`<tr><td>${r.id}</td><td>${r.agreement}</td><td>${nameRegion(r.region)}</td><td>${r.label}</td><td>${r.due}</td><td>${moneyText(r.amount)}</td><td>${moneyText(r.paid)}</td><td>${moneyText(r.amount-r.paid)}</td><td>${isHQ()&&r.paid<r.amount?`<button class="btn sm" onclick="receipt('${r.id}')">登记收款</button>`:'—'}</td></tr>`)+`<div class="panel" style="margin-top:18px"><h3>授权考核口径</h3><p class="muted">授权到期、合作费用、年度院校目标、培训合格人数、发证人数分别核查；涉及独家授权、违约及退出须依据正式合作协议及人工审批。</p></div>`}
window.addAgreement=()=>{if(!isHQ())return;modalV2('创建区域合作协议',[{...F('region','合作区域'),options:regionOpts()},F('number','协议编号','text','MVERI-COOP-2026-'),{...F('model','授权模式'),options:['省级非独家','市级非独家','特定项目授权','省级独家（需法务审批）'].map(x=>[x,x])},F('sign','签约日期','date'),F('start','生效日','date'),F('end','截止日','date'),F('amount','合作费总额（元）','number',0),F('memo','合作约定摘要','textarea','')],o=>{if(o.end<o.start)throw Error('协议结束日期不得早于开始日期');if(Number(o.amount)<0)throw Error('金额不能为负数');if(db.agreements.some(x=>x.number===o.number))throw Error('协议编号已经存在');db.agreements.push({...o,id:uid('agreements','G'),amount:+o.amount,first:0,second:0,stage:'待生效'});log('创建合作协议 '+o.number)},'仅建立合同台账，授权状态需单独审批')};
window.changeAgreement=id=>{let r=db.agreements.find(x=>x.id===id);if(!isHQ()||!r)return;modalV2('协议状态变更',[{...F('stage','目标状态'),options:['待生效','生效','暂停','终止','已到期'].map(x=>[x,x])},F('reason','变更原因与审批依据','textarea')],o=>{if(o.stage==='生效'&&db.partners.find(x=>x.id===r.region)?.status!=='有效')throw Error('该区域尚未获总部批准授权，不能激活协议');r.stage=o.stage;r.memo=(r.memo||'')+'；状态变更：'+o.reason;log('协议 '+id+' 变更为 '+o.stage)},'协议变更记录写入操作日志')};
window.addInstallment=()=>{if(!isHQ())return;modalV2('创建合同分期收款计划',[{...F('agreement','合作协议'),options:db.agreements.map(x=>[x.id,x.number])},F('label','分期名称'),F('due','到期日','date'),F('amount','应收金额（元）','number',0)],o=>{let a=db.agreements.find(x=>x.id===o.agreement);if(!a||Number(o.amount)<=0)throw Error('请选择协议并填写正数金额');let planned=db.paymentPlans.filter(x=>x.agreement===a.id).reduce((n,x)=>n+x.amount,0);if(planned+Number(o.amount)>a.amount)throw Error('分期计划总额不得超出协议金额');db.paymentPlans.push({...o,region:a.region,id:uid('paymentPlans','I'),amount:+o.amount,paid:0});log('新增合作费分期 '+a.id)})};
window.receipt=id=>{let r=db.paymentPlans.find(x=>x.id===id);if(!isHQ()||!r)return;modalV2('登记合同收款',[F('amount','本次实收金额（元）','number',r.amount-r.paid),F('date','实际收款日期','date',new Date().toISOString().slice(0,10)),F('reference','收款凭证编号')],o=>{let n=+o.amount;if(n<=0||n>r.amount-r.paid)throw Error('金额必须大于0且不超过剩余应收');r.paid+=n;let pa=db.partners.find(x=>x.id===r.region);if(pa)pa.paid=(pa.paid||0)+n;db.payments.push({id:uid('payments','F'),region:r.region,type:'合作费 '+r.label,amount:n,date:o.date,status:'已核销',reference:o.reference});log('分期收款核销 '+id+' '+n)},'必须有收款凭证号；模拟操作，不代表真实到账')};
function deliveryPage(){let op=db.opportunities.filter(owns),bs=db.batches.filter(owns),ls=db.learners.filter(owns);$('#view').innerHTML=banner('培训交付运营体系','院校商机 → 培训立项 → 排课开班 → 学员管理 → 学时考核 → 结班归档',role!=='college'?'<button class="btn" onclick="addOpportunity()">＋ 新建院校商机</button>':'')+`<div class="cards"><div class="metric"><div class="muted">院校商机</div><div class="value">${op.length}</div></div><div class="metric"><div class="muted">培训班次</div><div class="value">${bs.length}</div></div><div class="metric"><div class="muted">已结班批次</div><div class="value">${bs.filter(x=>x.status==='已结班').length}</div></div><div class="metric"><div class="muted">示例学员记录</div><div class="value">${ls.length}</div></div></div><div class="intro"><h2>一、院校商机与培训合同线索</h2></div>`+table(['商机','院校','项目需求','预计金额','阶段','最近跟进','操作'],op,r=>`<tr><td>${r.id}</td><td>${nameCollege(r.college)}</td><td>${esc(r.name)}</td><td>${moneyText(r.value)}</td><td>${stat(r.stage)}</td><td>${r.follow}</td><td>${isRegion()?`<button class="btn sm secondary" onclick="advanceOpportunity('${r.id}')">跟进</button>`:'—'}</td></tr>`)+`<div class="intro" style="margin-top:24px"><h2>二、培训实施与结班验收</h2>${isRegion()?'<button class="btn" onclick="addBatch()">＋ 新建培训班次</button>':''}</div>`+table(['批次','培训项目','课程/讲师','学时（已交付/要求）','出勤/考核','证明材料','状态','操作'],bs,r=>`<tr><td>${r.id}</td><td>${nameProgram(r.program)}</td><td>${esc(r.course)}<br>${esc(r.coach)}</td><td>${r.delivered}/${r.required} 学时</td><td>${r.attendance}% / ${r.assessment}%</td><td><span title="${esc(r.docs)}">${esc(r.docs||'未归档')}</span></td><td>${stat(r.status)}</td><td>${isRegion()?`<button class="btn sm secondary" onclick="updateBatch('${r.id}')">过程记录</button>${r.status!=='已结班'?`<button class="btn sm" onclick="closeBatch('${r.id}')">申请结班</button>`:''}`:'—'}</td></tr>`)+`<div class="intro" style="margin-top:24px"><h2>三、学员过程与能力结果</h2>${isRegion()?'<button class="btn" onclick="addLearner()">＋ 登记学员</button>':''}</div>`+table(['编号','姓名','批次','学时','成绩','结果','操作'],ls,r=>`<tr><td>${r.code}</td><td>${esc(r.name)}</td><td>${r.batch}</td><td>${r.hours}</td><td>${r.score}</td><td>${stat(r.status)}</td><td>${isRegion()?`<button class="btn sm secondary" onclick="updateLearner('${r.id}')">更新</button>`:'—'}</td></tr>`)+`<div class="notice mini">培训汇总人数为批次/项目的业务统计，学员明细是证据样例，不自动推导历史汇总人数；正式系统应通过导入与对账确保人数一致。</div>`}
window.addOpportunity=()=>{if(!isRegion())return;modalV2('新增院校培训商机',[{...F('college','关联院校'),options:collegeOpts()},F('name','项目需求名称'),F('contact','跟进人'),F('value','预计合同额','number',0),F('note','需求与下一步','textarea')],o=>{let c=db.colleges.find(x=>x.id===o.college);if(c?.region!==region)throw Error('只能选择本区域客户');db.opportunities.push({...o,id:uid('opportunities','O'),region,stage:'新线索',value:+o.value,follow:new Date().toISOString().slice(0,10)});log('新建商机 '+o.name)})};
window.advanceOpportunity=id=>{let r=db.opportunities.find(x=>x.id===id);if(!isRegion()||!r||r.region!==region)return;modalV2('商机跟进与推进',[{...F('stage','商机阶段'),options:['新线索','需求确认','方案报价','谈判中','已签约','已失单'].map(x=>[x,x])},F('note','跟进记录','textarea',r.note)],o=>{r.stage=o.stage;r.note=o.note;r.follow=new Date().toISOString().slice(0,10);log('更新商机 '+id+' '+o.stage)})};
window.addBatch=()=>{if(!isRegion())return;modalV2('创建培训实施班次',[{...F('program','培训项目'),options:programOpts().filter(([id])=>db.programs.find(x=>x.id===id)?.region===region)},F('course','课程/模块'),F('coach','授课教师'),F('required','应完成学时','number',32)],o=>{let p=db.programs.find(x=>x.id===o.program);if(!p||p.region!==region)throw Error('不能跨区建班');db.batches.push({...o,id:uid('batches','B'),region,required:+o.required,delivered:0,attendance:0,assessment:0,docs:'',status:'筹备中'});log('创建培训班次 '+o.program)})};
window.updateBatch=id=>{let r=db.batches.find(x=>x.id===id);if(!isRegion()||r?.region!==region)return;modalV2('更新培训过程与佐证',[F('delivered','已交付学时','number',r.delivered),F('attendance','出勤率（%）','number',r.attendance),F('assessment','考核合格率（%）','number',r.assessment),F('docs','归档材料清单或编号','textarea',r.docs)],o=>{for(let k of ['delivered','attendance','assessment'])o[k]=+o[k];if(o.delivered<0||o.attendance<0||o.attendance>100||o.assessment<0||o.assessment>100)throw Error('学时不能为负；百分比应在0~100之间');Object.assign(r,o);if(r.status!=='已结班')r.status=o.delivered?'培训中':'筹备中';log('更新班次过程记录 '+id)})};
window.closeBatch=id=>{let r=db.batches.find(x=>x.id===id);if(!isRegion()||r?.region!==region)return;if(r.delivered<r.required)return alert('课时不足，不能结班');if(r.attendance<80||r.assessment<60)return alert('未达到示例结班规则：出勤率≥80%，考核合格率≥60%');if(!r.docs.trim())return alert('请先登记结班归档材料');if(confirm('确认已核验培训资料并完成结班？')){r.status='已结班';log('结班验收 '+id);render(route())}};
window.addLearner=()=>{if(!isRegion())return;modalV2('登记学员明细',[{...F('batch','所属班次'),options:db.batches.filter(x=>x.region===region).map(x=>[x.id,x.id+' · '+nameProgram(x.program)])},F('name','姓名'),F('code','学员业务编号'),F('hours','完成学时','number',0),F('score','考核成绩','number',0)],o=>{if(db.learners.some(x=>x.code===o.code))throw Error('学员业务编号不可重复');let b=db.batches.find(x=>x.id===o.batch);if(!b||b.region!==region)throw Error('班次不属于当前区域');db.learners.push({...o,id:uid('learners','L'),region,hours:+o.hours,score:+o.score,status:+o.hours>=b.required&&+o.score>=60?'合格':'学习中'});log('登记学员 '+o.code)})};
window.updateLearner=id=>{let r=db.learners.find(x=>x.id===id);if(!isRegion()||r?.region!==region)return;modalV2('学员过程记录',[F('hours','完成学时','number',r.hours),F('score','考核成绩','number',r.score)],o=>{let b=db.batches.find(x=>x.id===r.batch);let h=+o.hours,sc=+o.score;if(h<0||sc<0||sc>100)throw Error('学时或成绩无效');r.hours=h;r.score=sc;r.status=h>=b.required&&sc>=60?'合格':'未合格';log('修改学员成绩 '+id)})};
function settlementPage(){let apps=db.certificates.filter(owns),ss=db.settlements.filter(owns),certs=db.certRecords.filter(owns);$('#view').innerHTML=banner('认证发证与费用结算体系','结班核验 → 区域报证 → 总部审批 → 生成证书 → 费用应收 → 收款核销')+`<div class="cards"><div class="metric"><div class="muted">已审核签发申请</div><div class="value">${apps.filter(x=>x.status==='已签发').length}</div></div><div class="metric"><div class="muted">证书记录（明细）</div><div class="value">${certs.length}</div></div><div class="metric"><div class="muted">证书服务应收</div><div class="value">${moneyText(ss.reduce((n,x)=>n+x.amount,0))}</div></div><div class="metric"><div class="muted">待核销</div><div class="value">${moneyText(ss.reduce((n,x)=>n+x.amount-x.paid,0))}</div></div></div><div class="panel"><h3>发证与结算控制点</h3><p class="muted">发证须经总部审定。通过后可根据通过人数形成结算单，结算单按约定单价计算，应收与实收分别管理。证书列表及核验均为离线模拟，不代表真实认证。</p></div><div class="intro" style="margin-top:24px"><h2>认证批次与结算处理</h2></div>`+table(['认证申请','区域','项目','申请/核准','状态','结算操作'],apps,r=>`<tr><td>${r.id}</td><td>${nameRegion(r.region)}</td><td>${nameProgram(r.program)}</td><td>${r.count}/${r.pass}</td><td>${stat(r.status)}</td><td>${isHQ()&&r.status==='已签发'?`<button class="btn sm" onclick="makeSettlement('${r.id}')">生成结算单</button>`:'—'}</td></tr>`)+`<div class="intro" style="margin-top:24px"><h2>服务费结算台账</h2></div>`+table(['结算单','申请编号','区域','核准人数','单价','应收金额','已核销','状态','操作'],ss,r=>`<tr><td>${r.id}</td><td>${r.application}</td><td>${nameRegion(r.region)}</td><td>${r.quantity}</td><td>${moneyText(r.unit)}</td><td>${moneyText(r.amount)}</td><td>${moneyText(r.paid)}</td><td>${stat(r.status)}</td><td>${isHQ()&&r.paid<r.amount?`<button class="btn sm" onclick="settlePayment('${r.id}')">收款核销</button>`:'—'}</td></tr>`)+`<div class="intro" style="margin-top:24px"><h2>证书核验记录（模拟）</h2></div>`+table(['证书编号','申请','所属中心','对应人员','状态','操作'],certs,r=>`<tr><td><b>${esc(r.number)}</b></td><td>${r.application}</td><td>${nameRegion(r.region)}</td><td>${esc(r.person)}</td><td>${stat(r.status)}</td><td>${isHQ()?`<button class="btn sm secondary" onclick="changeCertificate('${r.number}')">状态管理</button>`:'—'}</td></tr>`)+`<div class="notice mini">历史申请仅保留汇总人数，系统不会伪造全部学员证书明细。新签发时仅对可关联的合格学员明细生成模拟证书。</div>`}
window.makeSettlement=id=>{let r=db.certificates.find(x=>x.id===id);if(!isHQ()||r?.status!=='已签发')return;if(db.settlements.some(x=>x.application===id))return alert('当前申请已生成结算单，不可重复');modalV2('生成证书服务费用结算单',[F('unit','协议约定单价（元/人）','number',160),F('note','计费依据/审批编号')],o=>{let u=+o.unit;if(u<0)throw Error('单价不可为负');let qty=r.pass;db.settlements.push({id:uid('settlements','S'),region:r.region,application:id,unit:u,quantity:qty,amount:u*qty,paid:0,status:'待确认',date:new Date().toISOString().slice(0,10),note:o.note});log('生成证书服务结算 '+id)},'单价为示例值；以实际合同为准')};
window.settlePayment=id=>{let r=db.settlements.find(x=>x.id===id);if(!isHQ()||!r)return;modalV2('证书服务费收款核销',[F('amount','实收金额（元）','number',r.amount-r.paid),F('date','到账日期','date',new Date().toISOString().slice(0,10)),F('reference','银行流水/凭证编号')],o=>{let n=+o.amount;if(n<=0||n>r.amount-r.paid)throw Error('金额不得超过未结算余额');r.paid+=n;r.status=r.paid===r.amount?'已结清':'部分收款';db.payments.push({id:uid('payments','F'),region:r.region,type:'证书服务费 '+id,amount:n,date:o.date,status:'已核销',reference:o.reference});log('证书费核销 '+id+' '+n)})};
window.changeCertificate=number=>{let r=db.certRecords.find(x=>x.number===number);if(!isHQ()||!r)return;modalV2('证书状态审核管理',[{...F('status','新状态'),options:['有效','已撤销','暂停核验'].map(x=>[x,x])},F('reason','操作依据与原因','textarea')],o=>{r.status=o.status;r.reason=o.reason;log('证书状态修改 '+number+' '+o.status)},'模拟核验；正式版本应具备审批权限与电子签章')};
// Add an auditable per-person mock record only when specific eligible learner data exist.
const originalReviewCert=window.reviewCert;
window.reviewCert=(id,pass)=>{let before=db.certificates.find(x=>x.id===id)?.status;originalReviewCert(id,pass);let r=db.certificates.find(x=>x.id===id);if(pass&&before==='待总部审核'&&r?.status==='已签发'){let ps=db.batches.filter(x=>x.program===r.program&&x.status==='已结班'),ids=ps.map(x=>x.id),eligible=db.learners.filter(x=>ids.includes(x.batch)&&x.status==='合格').slice(0,r.pass);eligible.forEach(l=>{if(!db.certRecords.some(x=>x.application===r.id&&x.learner===l.id))db.certRecords.push({number:'MVERI-DEMO-'+r.id+'-'+l.id,application:r.id,region:r.region,learner:l.id,person:l.name,status:'有效'})});log('审核完成：生成 '+eligible.length+' 条可核验示例学员证书明细');render(route())}};

// V3.0 — connected business workflows. All writes are to the same browser-local db.
MODULES.splice(1,0,['journey','↗','业务贯通中心']);
const V3={version:'3.0',today:()=>new Date().toISOString().slice(0,10),own:r=>isHQ()||r.region===region,agreement:r=>db.agreements.find(a=>a.region===r&&a.stage==='生效'&&a.start<=V3.today()&&a.end>=V3.today()),active:r=>db.partners.find(p=>p.id===r)?.status==='有效'&&!!V3.agreement(r),qty:r=>db.learners.filter(l=>l.batch===r&&l.status==='合格'),completed:p=>db.batches.filter(b=>b.program===p&&b.status==='已结班'), issued:p=>db.certificates.filter(a=>a.program===p&&a.status==='已签发').reduce((v,a)=>v+a.pass,0),sum:(arr,k)=>arr.reduce((n,x)=>n+Number(x[k]||0),0)};
const oldRender=render;
render=function(page){if(page==='journey')journeyPage();else oldRender(page)};
const oldNavVisible=navVisible;
navVisible=function(id){return id==='journey'?true:oldNavVisible(id)};
function regionSummary(r){let ag=db.agreements.filter(x=>x.region===r),t=db.targets.filter(x=>x.region===r&&+x.year===2026),ops=db.opportunities.filter(x=>x.region===r),ps=db.programs.filter(x=>x.region===r),bs=db.batches.filter(x=>x.region===r),app=db.certificates.filter(x=>x.region===r),ss=db.settlements.filter(x=>x.region===r),plans=db.paymentPlans.filter(x=>x.region===r),certV=app.filter(x=>x.status==='已签发'),train=V3.sum(ps,'completed'),issued=V3.sum(certV,'pass');return {r,ag,t,ops,ps,bs,app,ss,plans,train,issued,paid:V3.sum(ss,'paid')+V3.sum(plans,'paid'),receivable:ss.reduce((n,x)=>n+x.amount-x.paid,0)+plans.reduce((n,x)=>n+x.amount-x.paid,0),target:V3.sum(t,'students'),certTarget:V3.sum(t,'certificates')}}
function journeyPage(){let regions=isHQ()?db.partners.map(p=>p.id):[region],summaries=regions.map(regionSummary),selected=sessionStorage.getItem('v3selected')||regions[0],r=regions.includes(selected)?selected:regions[0],s=regionSummary(r),valid=V3.active(r);let groups=[['授权','agreements',s.ag.filter(x=>x.stage==='生效').length,'有效协议'],['目标','targets',s.t.length,'年度任务'],['商机','delivery',s.ops.filter(x=>x.stage==='已签约').length,'签约线索'],['交付','delivery',s.bs.filter(x=>x.status==='已结班').length,'已结班批次'],['认证','certificates',s.app.filter(x=>x.status==='已签发').length,'签发申请'],['结算','settlement',s.ss.length,'结算单']];$('#view').innerHTML=banner('三大体系业务数据贯通','统一业务主键、跨模块自动创建、校验阻断、关联台账与实时经营汇总')+`<div class="toolbar"><label>查看区域 <select id="journeyRegion">${regions.map(id=>`<option value="${esc(id)}" ${id===r?'selected':''}>${esc(nameRegion(id))}</option>`).join('')}</select></label><a class="btn secondary" href="agreements.html">协议与授权</a><a class="btn secondary" href="delivery.html">培训交付</a><a class="btn secondary" href="settlement.html">认证结算</a></div><div class="notice">${esc(nameRegion(r))} · 授权状态：${valid?'有效':'无当前有效授权'}。${valid?'可由区域推进交付业务':'没有有效授权时，不允许自动转化新培训项目或报证。'} 系统所有数据均为离线模拟。</div><div class="cards"><div class="metric"><div class="muted">年度培训目标 / 已结班</div><div class="value">${s.train} / ${s.target}</div><div class="tag">达成率 ${s.target?Math.round(s.train/s.target*100):0}%</div></div><div class="metric"><div class="muted">年度认证目标 / 已签发</div><div class="value">${s.issued} / ${s.certTarget}</div><div class="tag">与结班合格数分别核算</div></div><div class="metric"><div class="muted">合同与认证累计已核销</div><div class="value">${money(s.paid)}</div></div><div class="metric"><div class="muted">当前剩余应收</div><div class="value">${money(s.receivable)}</div></div></div><div class="panel"><h3>跨模块业务链路 · 点击查看原始台账</h3><div class="flowline">${groups.map((g,i)=>`<a class="stage" href="${g[1]}.html"><b>0${i+1} ${g[0]}</b><strong style="display:block;font-size:23px">${g[2]}</strong><small>${g[3]}</small></a>`).join('')}</div></div><div class="intro" style="margin-top:24px"><h2>自动衔接操作</h2></div><div class="grid2"><div class="panel"><h3>① 协议生效 → 年度任务</h3><p class="muted">根据有效协议及区域授权生成对应年度任务；已经存在的年度任务不会重复创建。</p>${isHQ()?`<button class="btn" onclick="v3Target('${r}')">核验并生成年度任务</button>`:'<span class="muted">仅总部可执行</span>'}</div><div class="panel"><h3>② 商机签约 → 培训项目</h3><p class="muted">签约商机可转成培训项目，自动继承院校、所属区域与业务来源编号。</p>${isRegion()?`<button class="btn" onclick="v3OpenConvert('${r}')">选择商机并立项</button>`:'<span class="muted">仅区域中心可执行</span>'}</div><div class="panel"><h3>③ 结班合格 → 认证申请</h3><p class="muted">从已结班批次中筛选学时与考核合格学员；申请保留学员编号，避免只报汇总人数。</p>${isRegion()?`<button class="btn" onclick="v3OpenApplication('${r}')">从结班名单发起报证</button>`:'<span class="muted">仅区域中心可执行</span>'}</div><div class="panel"><h3>④ 总部签发 → 证书与结算</h3><p class="muted">审核通过后自动生成对应学员模拟证书、按协议计费单价生成应收单，资金到账后再核销。</p>${isHQ()?`<button class="btn" onclick="v3OpenApproval('${r}')">审核待办并签发</button>`:'<span class="muted">仅总部可执行</span>'}</div></div><div class="intro" style="margin-top:24px"><h2>业务证据链与状态核对</h2></div>`+table(['业务对象','来源关联','培训状态','认证情况','结算情况','详情'],s.ps,rp=>{let b=db.batches.filter(x=>x.program===rp.id),a=db.certificates.filter(x=>x.program===rp.id),ss=db.settlements.filter(x=>a.some(v=>v.id===x.application)),op=db.opportunities.find(x=>x.id===rp.opportunity);return `<tr><td><b>${esc(rp.id)} · ${esc(rp.name)}</b><br><span class="muted">${esc(nameCollege(rp.college))}</span></td><td>${esc(op?.id||rp.opportunity||'历史项目')}<br>${esc(op?.stage||'—')}</td><td>${b.filter(x=>x.status==='已结班').length}/${b.length} 批结班<br>${rp.completed} 人合格</td><td>${a.length} 份申请<br>${a.filter(x=>x.status==='已签发').length} 份已签发</td><td>${ss.length} 张结算单<br>${money(V3.sum(ss,'paid'))} 已核销</td><td><button class="btn sm secondary" onclick="v3Trace('${rp.id}')">追溯</button></td></tr>`})+`<div class="intro" style="margin-top:24px"><h2>区域经营联动对账</h2></div>`+table(['区域','授权','培训目标','结班合格','认证目标','已签发','费用已收','应收余额'],summaries.map(x=>({...x})),x=>`<tr><td>${nameRegion(x.r)}</td><td>${V3.active(x.r)?stat('有效'):stat('待核查')}</td><td>${x.target}</td><td>${x.train}</td><td>${x.certTarget}</td><td>${x.issued}</td><td>${money(x.paid)}</td><td>${money(x.receivable)}</td></tr>`);$('#journeyRegion').onchange=e=>{sessionStorage.setItem('v3selected',e.target.value);journeyPage()}}
window.v3Target=r=>{if(!isHQ())return;if(!V3.active(r))return alert('授权未生效或已过期，不能生成年度任务');let a=V3.agreement(r),year=Number(a.start.slice(0,4));if(db.targets.some(x=>x.region===r&&Number(x.year)===year))return alert('该年度任务已存在，不重复生成');if(!confirm(`为${nameRegion(r)}创建${year}年度任务？`))return;db.targets.push({id:uid('targets','T'),region:r,year,students:db.partners.find(x=>x.id===r)?.quota||0,colleges:10,certificates:Math.round((db.partners.find(x=>x.id===r)?.quota||0)*.8),agreement:a.id,auto:true});log('自动创建年度任务，来源协议 '+a.id);render('journey')};
window.v3OpenConvert=r=>{if(!isRegion()||region!==r)return;if(!V3.active(r))return alert('当前区域无有效合作授权');let candidates=db.opportunities.filter(x=>x.region===r&&x.stage==='已签约'&&!db.programs.some(p=>p.opportunity===x.id));if(!candidates.length)return alert('没有可转换的已签约商机，或已全部转成培训项目');modalV2('签约商机转换培训项目',[{...F('opportunity','签约商机'),options:candidates.map(x=>[x.id,x.id+' · '+x.name])},F('planned','计划培训人数','number',60),F('start','开始日期','date',V3.today()),F('end','结束日期','date',V3.today())],o=>{let x=db.opportunities.find(v=>v.id===o.opportunity);if(!x||x.region!==region||x.stage!=='已签约'||db.programs.some(p=>p.opportunity===x.id))throw Error('商机已被转化或无权操作');if(!V3.active(region))throw Error('合作授权未生效');if(+o.planned<=0||o.end<o.start)throw Error('人数与日期无效');let p={id:uid('programs','P'),region,college:x.college,name:x.name,start:o.start,end:o.end,planned:+o.planned,enrolled:0,completed:0,status:'招生中',opportunity:x.id,agreement:V3.agreement(region).id};db.programs.push(p);x.project=p.id;log('商机 '+x.id+' 转培训项目 '+p.id)})};
window.v3OpenApplication=r=>{if(!isRegion()||region!==r)return;if(!V3.active(r))return alert('区域合作授权无效');let available=db.programs.filter(p=>p.region===r&&V3.completed(p.id).length&&V3.completed(p.id).some(b=>V3.qty(b.id).some(l=>!db.certificates.some(a=>a.learnerIds?.includes(l.id)&&a.status!=='草稿'))));if(!available.length)return alert('没有可报证的合格学员。请先完成结班和学员成绩核验');modalV2('基于合格学员创建认证申请',[{...F('program','已结班项目'),options:available.map(p=>[p.id,p.name])},F('note','本次申请依据','textarea','结班及考核合格学员名单')],o=>{let p=db.programs.find(x=>x.id===o.program);if(!p||p.region!==region||!V3.active(region))throw Error('项目或授权不符合要求');let ids=V3.completed(p.id).flatMap(b=>V3.qty(b.id).map(l=>l.id));ids=ids.filter(id=>!db.certificates.some(a=>a.learnerIds?.includes(id)&&a.status!=='草稿'));if(!ids.length)throw Error('无可报证合格学员');let app={id:uid('certificates','A'),region,program:p.id,count:ids.length,pass:ids.length,status:'待总部审核',learnerIds:ids,opinion:'',date:V3.today(),note:o.note,agreement:V3.agreement(region).id};db.certificates.push(app);log('结班合格名单自动生成认证申请 '+app.id+'，'+ids.length+'人')})};
window.v3OpenApproval=r=>{if(!isHQ())return;let apps=db.certificates.filter(a=>a.region===r&&a.status==='待总部审核');if(!apps.length)return alert('该区域暂无待审核申请');modalV2('总部核验并批准认证申请',[{...F('application','待审核申请'),options:apps.map(x=>[x.id,x.id+' · '+nameProgram(x.program)+' · '+x.count+'人'])},F('unit','证书服务计费单价（元/人）','number',160),F('opinion','总部审核意见','textarea','名单、学时及成绩复核通过')],o=>{let a=db.certificates.find(x=>x.id===o.application),p=db.programs.find(x=>x.id===a?.program);if(!a||a.status!=='待总部审核'||!p)throw Error('申请不存在或已处理');if(!V3.active(a.region))throw Error('合作授权失效，需人工核查');if(!a.learnerIds?.length)throw Error('历史汇总型申请缺少学员明细，请先补录名单，不允许自动发证');let ids=[...new Set(a.learnerIds)],batches=V3.completed(p.id).map(x=>x.id);let eligible=ids.every(id=>{let l=db.learners.find(x=>x.id===id);return l&&batches.includes(l.batch)&&l.status==='合格'&&!db.certRecords.some(c=>c.learner===id&&c.status==='有效')});if(!eligible)throw Error('存在未结班、未合格、重复或缺失的学员，阻止签发');if(+o.unit<0||!String(o.opinion||'').trim())throw Error('单价无效或审核意见为空');a.pass=ids.length;a.count=ids.length;a.opinion=o.opinion;a.status='已签发';a.batch='MVERI-DEMO-'+a.id;ids.forEach(id=>{let l=db.learners.find(x=>x.id===id);db.certRecords.push({number:'MVERI-DEMO-'+a.id+'-'+id,application:a.id,region:a.region,learner:id,person:l.name,status:'有效'})});if(!db.settlements.some(x=>x.application===a.id))db.settlements.push({id:uid('settlements','S'),region:a.region,application:a.id,unit:+o.unit,quantity:ids.length,amount:ids.length*(+o.unit),paid:0,status:'待确认',date:V3.today(),agreement:a.agreement||'',note:'名单审批自动生成'});log('总部审核签发 '+a.id+'，'+ids.length+'人，同步建立应收结算')},'仅生成演示证书，不具有正式认证效力')};
window.v3Trace=id=>{let p=db.programs.find(x=>x.id===id);if(!p||!V3.own(p))return;let op=db.opportunities.find(x=>x.id===p.opportunity),bs=db.batches.filter(x=>x.program===id),as=db.certificates.filter(x=>x.program===id),ss=db.settlements.filter(x=>as.some(a=>a.id===x.application));let msg=`项目：${p.id} ${p.name}\n区域：${nameRegion(p.region)}\n协议：${p.agreement||'历史无关联'}\n商机：${op?.id||'历史无关联'}\n院校：${nameCollege(p.college)}\n培训批次：${bs.map(x=>x.id+'('+x.status+')').join('、')||'无'}\n认证申请：${as.map(x=>x.id+'('+x.status+')').join('、')||'无'}\n结算单：${ss.map(x=>x.id+'(已收'+x.paid+'/'+x.amount+')').join('、')||'无'}`;alert(msg)};
// Normalize old learner qualification by objective requirements; do not trust legacy status alone.
V3.qty=r=>{let b=db.batches.find(x=>x.id===r);return db.learners.filter(l=>l.batch===r&&b&&l.hours>=b.required&&l.score>=60&&l.status==='合格')};
const originalCloseBatch=window.closeBatch;
window.closeBatch=id=>{let b=db.batches.find(x=>x.id===id);if(!b||!isRegion()||b.region!==region)return;const before=b.status;originalCloseBatch(id);if(before!=='已结班'&&b.status==='已结班'){let p=db.programs.find(x=>x.id===b.program);if(p){let finished=V3.completed(p.id);let count=new Set(finished.flatMap(v=>V3.qty(v.id).map(l=>l.id))).size;p.completed=count;p.status='已结班';log('结班同步刷新项目 '+p.id+' 合格人数 '+count);render(route())}}};
const originalReview=window.reviewCert;
window.reviewCert=(id,pass)=>{const a=db.certificates.find(x=>x.id===id);if(pass)return alert(a?.learnerIds?.length?'请到「业务贯通中心」执行总部审核签发，以同时形成学员证书与应收结算单':'历史申请缺少可核对的学员明细，不能直接签发。请在培训交付中心补录学员并使用业务贯通中心重新申报。');originalReview(id,pass)};
