// V3.8: Keep the permanent SPA shell; collapse only changes its width and presentation.
window.applySidebarPreference=function(){
  const shell=document.querySelector('.shell');if(!shell)return;
  const collapsed=localStorage.getItem('mveriSidebarCollapsed')==='1' && window.matchMedia('(min-width:721px)').matches;
  shell.classList.toggle('sidebar-collapsed',collapsed);
  const btn=document.getElementById('sidebarToggle');
  if(btn){btn.setAttribute('aria-expanded',String(!collapsed));btn.setAttribute('aria-label',collapsed?'展开侧边导航':'收起侧边导航');btn.title=collapsed?'展开侧边导航':'收起侧边导航';}
};
window.toggleSidebar=function(){
  const shell=document.querySelector('.shell');if(!shell)return;
  if(window.matchMedia('(max-width:720px)').matches){document.getElementById('sidebar')?.classList.remove('open');return;}
  const collapsed=!shell.classList.contains('sidebar-collapsed');
  localStorage.setItem('mveriSidebarCollapsed',collapsed?'1':'0');
  window.applySidebarPreference();
};
window.addEventListener('resize',()=>window.applySidebarPreference());


// V67 — persistent shell routing for area-owned modules. No second shell, no page reload.
(function(){
  const validRoutes=new Set([...MODULES.map(m=>m[0]),'journey'].filter(id=>(!id.startsWith('eval-')||assessmentPages.has(id))&&isAllowedRoute(id)));
  const groupKey='mveri_nav_group_v63_'+role;
  const getRoute=(url)=>{
    if(url.origin!==location.origin || url.pathname.slice(0,url.pathname.lastIndexOf('/')+1)!==location.pathname.slice(0,location.pathname.lastIndexOf('/')+1))return null;
    const match=/\/([a-z-]+)\.html$/.exec(url.pathname);
    if(!match || !validRoutes.has(match[1]) || url.hash)return null;
    return match[1];
  };
  let lastDisplayedRoute=route();
  function showRoute(next,restoreScroll){
    const view=document.getElementById('view'),nav=document.querySelector('.nav');
    if(!view||!nav||!validRoutes.has(next))return;
    document.getElementById('overlay')?.replaceChildren();
    // Only business content changes: sidebar and header nodes retain their identity.
    view.replaceChildren();
    window.__mveriRequestedRoute=next;
    try{render(next)}finally{window.__mveriRequestedRoute=null}
    const title=MODULES.find(m=>m[0]===next)?.[2]||'工作台';
    const h=document.querySelector('.workspace-heading h1'); if(h)h.textContent=title;
    const crumb=document.querySelector('.workspace-breadcrumb');if(crumb)crumb.textContent=(role==='hq'?'总部运营':role==='region'?'区域服务':'院校服务')+' / '+title;
    document.title=title+' · '+(role==='hq'?'总部运营平台':'全国区域服务协作平台');
    lastDisplayedRoute=next;
    const links=[...nav.querySelectorAll('a[href]')];
    let activeGroup=null;
    links.forEach(a=>{
      const target=a.dataset.route||getRoute(new URL(a.href,location.href));const active=target===next;
      a.classList.toggle('active',active);
      if(active){a.setAttribute('aria-current','page');activeGroup=a.closest('.nav-accordion-group')}
      else a.removeAttribute('aria-current');
      a.querySelector('.nav-current')?.remove();
      if(active){const dot=document.createElement('b');dot.className='nav-current';a.append(dot)}
    });
    if(activeGroup){
      nav.querySelectorAll('.nav-accordion-group').forEach(g=>{
        const open=g===activeGroup;
        g.classList.toggle('is-open',open);
        const btn=g.querySelector('.nav-accordion-trigger');if(btn)btn.setAttribute('aria-expanded',String(open));
        const panel=g.querySelector('.nav-accordion-panel');if(panel)panel.hidden=!open;
      });
      sessionStorage.setItem(groupKey,activeGroup.dataset.group||'');
    }
    if(!restoreScroll){const main=document.querySelector('.shell>.main');if(main)main.scrollTop=0;view.scrollTop=0;try{assessmentFrame?.contentWindow?.document?.querySelector('main#main')?.scrollTo({top:0,behavior:'instant'})}catch(_){}}
  }
  document.addEventListener('click',e=>{
    if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.altKey||e.shiftKey)return;
    const a=e.target.closest('a[href]');
    if(!a||!a.closest('.shell')||a.hasAttribute('download')||a.target==='_blank')return;
    const next=a.dataset.route||getRoute(new URL(a.href,location.href));
    if(!validRoutes.has(next))return;
    e.preventDefault();
    if(route()!==next)history.pushState({mveriRoute:next},'',location.pathname+location.search+'#'+next);
    showRoute(next,false);
    if(window.matchMedia('(max-width:720px)').matches)document.getElementById('sidebar')?.classList.remove('open');
  });
  window.addEventListener('popstate',()=>{const next=route();if(next!==lastDisplayedRoute)showRoute(validRoutes.has(next)?next:'dashboard',true)});
  window.addEventListener('hashchange',()=>{const next=route();if(validRoutes.has(next)&&next!==lastDisplayedRoute)showRoute(next,true)});
})();


/* V72.31 — centrally managed demo permission grants, scoped to organization, role and account.
   Only module visibility/route filtering can be enforced in the present browser-only login.
   Operation grants are stored and displayed but require server-side checks in production. */
const PERMISSION_MODULES=[
 ['工作空间',[['dashboard','经营驾驶舱'],['journey','业务贯通中心']]],
 ['能力评价体系',[['eval-home','运营总览'],['eval-indicators','指标体系'],['eval-masterdata','主数据模型'],['eval-points','考评点管理'],['eval-types','题型管理'],['eval-plans','命题计划'],['eval-bank','试题维护'],['eval-blueprint','测评蓝图'],['eval-agents','专项智能体'],['eval-data','数据管理']]],
 ['合作经营',[['ecosystem-partners','合作伙伴管理'],['partners','区域合作管理'],['agreements','合作协议与授权'],['targets','年度任务管理']]],
 ['培训业务',[['colleges','院校客户管理'],['programs','培训项目管理'],['delivery','培训交付中心']]],
 ['认证与结算',[['certificates','认证与证书'],['settlement','认证结算中心'],['finance','费用与绩效']]],
 ['组织与授权',[['school-admin','院校管理'],['user-admin','用户管理'],['permissions','权限分配']]],
 ['系统管理',[['audit','操作日志']]]
];
const PERMISSION_ACTS=['view','edit','review','manage'];
const PERMISSION_LABELS={view:'查看',edit:'新增／编辑',review:'审核',manage:'管理'};
const PERMISSION_KEY='mveri_module_grants_v7231';
const permissionKey=u=>u.group+'::'+u.id;
function permissionRead(){try{const x=JSON.parse(localStorage.getItem(PERMISSION_KEY)||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{}}catch{return {}}}
function permissionWrite(x){localStorage.setItem(PERMISSION_KEY,JSON.stringify(x))}
function permissionPreset(u){
 const ids=PERMISSION_MODULES.flatMap(g=>g[1].map(x=>x[0]));
 const group=u.group;
 const getDefault=(id)=>{
  if(group==='hq')return u.role==='平台管理员'||u.account==='admin'?['view','edit','review','manage']:(u.role==='标准管理员'? (id.startsWith('eval-')?['view','edit','review']:['view']):u.role==='认证审核员'?(id==='certificates'||id==='settlement'?['view','review']:['view']):['view','edit']);
  if(group==='region')return ['dashboard','targets','colleges','programs','delivery','certificates','settlement','finance'].includes(id)?['view','edit']:[];
  if(group==='school')return ['dashboard','colleges','programs','delivery','certificates'].includes(id)?['view',...(u.role==='管理员'?['edit']:[])]:[];
  return [];
 };
 return Object.fromEntries(ids.map(id=>[id,getDefault(id)]));
}
function permissionApplyTemplate(u,template){const ids=PERMISSION_MODULES.flatMap(g=>g[1].map(x=>x[0]));return Object.fromEntries(ids.map(id=>{
 if(template==='viewer')return ['view'];
 if(template==='operator')return ['view','edit'];
 if(template==='auditor')return ['view','review'];
 if(template==='administrator')return ['view','edit','review','manage'];
 return permissionPreset(u)[id]||[];
}));}
let permissionSelected='',permissionGroup='all',permissionQuery='',permissionDraft=null;
function renderPermissions(){
 if(!isHQ()){document.getElementById('view').innerHTML='<section class="panel">仅总部管理员可以分配权限</section>';return}
 const all=window.MVERI_USERS.all();const stored=permissionRead();
 const items=all.filter(u=>(permissionGroup==='all'||permissionGroup===u.group)&&(!permissionQuery||[u.name,u.account,u.role,u.unit].join(' ').toLowerCase().includes(permissionQuery.toLowerCase())));
 let selected=all.find(u=>permissionKey(u)===permissionSelected);
 if(!selected&&items.length){selected=items[0];permissionSelected=permissionKey(selected);permissionDraft=null}
 const data=selected?(permissionDraft||JSON.parse(JSON.stringify(stored[permissionSelected]?.modules||permissionPreset(selected)))):null;
 const options=[['all','全部身份'],['hq','研究院总部'],['region','区域中心'],['school','院校／教师'],['personal','个人注册']];
 const table=selected?PERMISSION_MODULES.map(([group,modules])=>{
 const permitted=modules.filter(([id])=>window.MVERI_UNIFIED_MENU.allowed(id,selected.group==='hq'?'hq':selected.group==='region'?'region':'college'));
 return `<section class="permission-cluster"><div class="permission-cluster-head"><strong>${esc(group)}</strong><small>${permitted.length} 个可配置模块</small></div>${permitted.map(([id,title])=>{const grants=data[id]||[];const reserved=id==='permissions'||id==='user-admin';return `<div class="permission-item"><span class="permission-item-label">${esc(title)} ${reserved?'<small>敏感模块</small>':''}</span><div class="permission-flags">${PERMISSION_ACTS.map(a=>`<label><input type="checkbox" data-perm-id="${id}" data-perm-act="${a}" ${grants.includes(a)?'checked':''} ${selected.account==='admin'?'disabled':''}><span>${PERMISSION_LABELS[a]}</span></label>`).join('')}</div></div>`}).join('')}</section>`}).join(''):'<div class="permission-empty">无可配置账号</div>';
 const stats=[['用户账户',all.length],['已配置权限',Object.keys(stored).length],['总部账号',all.filter(x=>x.group==='hq').length],['组织类别',4]];
 document.getElementById('view').innerHTML=`<div class="intro"><div><h2>权限分配</h2><p class="muted">按组织与账号配置模块查看、编辑、审核和管理权限；统一角色模板，变更可追溯。</p></div></div><section class="permission-summary">${stats.map(([n,v])=>`<div class="user-kpi"><span>${n}</span><strong>${v}</strong></div>`).join('')}</section><div class="permission-layout"><aside class="permission-users"><div class="permission-head"><h3>授权对象</h3><span>${items.length} 人</span></div><label class="permission-search"><span>所属身份</span><select id="permissionGroup">${options.map(([id,t])=>`<option value="${id}" ${permissionGroup===id?'selected':''}>${t}</option>`).join('')}</select></label><label class="permission-search"><span>查找账号</span><input id="permissionSearch" value="${esc(permissionQuery)}" placeholder="账号、姓名、岗位"></label><div class="permission-user-list">${items.map(u=>`<button type="button" class="permission-user ${permissionSelected===permissionKey(u)?'active':''}" data-user-key="${esc(permissionKey(u))}"><strong>${esc(u.name||u.account)}</strong><small>${esc(u.account)} · ${esc(u.role)} · ${esc(u.unit)}</small></button>`).join('')||'<p class="muted">没有符合条件的账号</p>'}</div></aside><section class="permission-editor">${selected?`<header class="permission-editor-head"><div><div class="permission-tag">账号权限矩阵</div><h3>${esc(selected.name||selected.account)} <small>${esc(selected.account)}</small></h3><p>所属：${esc(selected.unit)} · 角色：${esc(selected.role)} · 账号状态：${esc(selected.status)}</p></div><div class="permission-actions"><label>套用模板 <select id="permissionTemplate"><option value="">选择模板</option><option value="default">岗位默认</option><option value="viewer">只读查看</option><option value="operator">业务经办</option><option value="auditor">审核人员</option><option value="administrator">全部权限</option></select></label><button class="btn secondary" id="permissionReset">撤销修改</button><button class="btn" id="permissionSave" ${selected.account==='admin'?'disabled':''}>保存授权</button></div></header>${selected.account==='admin'?'<div class="permission-notice">默认管理员的全部权限不可修改，避免误操作导致系统失去管理入口。</div>':''}<div class="permission-matrix-head"><span>业务模块</span><span>功能权限</span></div>${table}<div class="permission-usage">说明：勾选“新增／编辑、审核、管理”会自动包含“查看”。授权只允许在该用户原有组织与角色可访问的业务范围内配置。当前浏览器离线演示仅能对演示登录账号进行菜单／路由可见性控制；具体按钮和业务数据操作需要正式服务端权限校验。</div>`:'<p>请选择账号</p>'}</section></div>`;
 document.querySelector('#permissionGroup')?.addEventListener('change',e=>{permissionGroup=e.target.value;permissionDraft=null;renderPermissions()});
 document.querySelector('#permissionSearch')?.addEventListener('input',e=>{permissionQuery=e.target.value.trim();const pos=e.target.selectionStart;renderPermissions();const input=document.getElementById('permissionSearch');input?.focus();input?.setSelectionRange(pos,pos)});
 document.querySelectorAll('[data-user-key]').forEach(btn=>btn.addEventListener('click',()=>{permissionSelected=btn.dataset.userKey;permissionDraft=null;renderPermissions()}));
 document.querySelectorAll('[data-perm-id]').forEach(box=>box.addEventListener('change',()=>{const id=box.dataset.permId,act=box.dataset.permAct;if(!permissionDraft)permissionDraft=JSON.parse(JSON.stringify(data));const set=new Set(permissionDraft[id]||[]);box.checked?set.add(act):set.delete(act);if(act!=='view'&&box.checked)set.add('view');if(act==='view'&&!box.checked)set.clear();permissionDraft[id]=[...set];renderPermissions()}));
 document.getElementById('permissionTemplate')?.addEventListener('change',e=>{if(!e.target.value)return;permissionDraft=permissionApplyTemplate(selected,e.target.value);renderPermissions()});
 document.getElementById('permissionReset')?.addEventListener('click',()=>{permissionDraft=null;renderPermissions()});
 document.getElementById('permissionSave')?.addEventListener('click',()=>{if(!selected||selected.account==='admin')return;const modules=permissionDraft||data;const allowed={};for(const group of PERMISSION_MODULES)for(const [id] of group[1]){const selectedRole=selected.group==='hq'?'hq':selected.group==='region'?'region':'college';if(!window.MVERI_UNIFIED_MENU.allowed(id,selectedRole))continue;const acts=(modules[id]||[]).filter(x=>PERMISSION_ACTS.includes(x));allowed[id]=acts.includes('view')?acts:[];}const x=permissionRead();x[permissionSelected]={account:selected.account,group:selected.group,unit:selected.unit,role:selected.role,modules:allowed,updatedAt:new Date().toISOString()};permissionWrite(x);permissionDraft=null;log('权限分配：'+selected.account+' '+Object.values(allowed).filter(a=>a.includes('view')).length+' 个模块');renderPermissions();alert('权限配置已保存到当前浏览器，演示账号下次切换菜单将应用查看权限。')});
}


/* V72.37: stand-alone ecosystem partner management; independent of regional service center partners. */
let ecosystemTypeFilter='all',ecosystemStatusFilter='all',ecosystemText='';
function renderEcosystemPartners(){
 const host=document.getElementById('view');if(!host)return;
 if(!isHQ()){host.innerHTML='<div class="panel">仅总部可管理合作伙伴</div>';return}
 const api=window.MVERI_PARTNER_REGISTRY;
 if(!api){host.innerHTML='<div class="panel">合作伙伴数据模块未加载，请检查 partner-registry-v7237.js</div>';return}
 const all=api.get();const rows=all.filter(x=>(ecosystemTypeFilter==='all'||x.type===ecosystemTypeFilter)&&(ecosystemStatusFilter==='all'||x.status===ecosystemStatusFilter)&&[x.name,x.contact,x.id].join(' ').toLowerCase().includes(ecosystemText.toLowerCase()));
 const categories=['科技企业','职业院校','央企','教育科技','培训机构','行业组织','其他'];const statuses=['待审核','已通过','已驳回','已停用'];
 host.innerHTML=`<section class="epm"><div class="intro"><div><h2>合作伙伴管理</h2><p class="muted">机构入驻 · 资质审核 · 合作授权 · 资源共建 · 项目协同 · 运营留痕。与区域服务中心授权台账独立。</p></div><button class="btn" onclick="epmNew()">＋ 新增合作伙伴</button></div><div class="cards"><div class="metric"><small>合作伙伴总数</small><div class="value">${all.length}</div></div><div class="metric"><small>待审核</small><div class="value">${all.filter(x=>x.status==='待审核').length}</div></div><div class="metric"><small>已通过</small><div class="value">${all.filter(x=>x.status==='已通过').length}</div></div><div class="metric"><small>资源待审核</small><div class="value">${all.reduce((n,x)=>n+(x.resources||[]).filter(r=>r.status==='待审核').length,0)}</div></div></div>
 <div class="panel"><div class="epm-filters"><label>类别<select id="epmType"><option value="all">全部类别</option>${categories.map(x=>`<option ${ecosystemTypeFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><label>入驻状态<select id="epmStatus"><option value="all">全部状态</option>${statuses.map(x=>`<option ${ecosystemStatusFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><label>搜索<input id="epmSearch" value="${esc(ecosystemText)}" placeholder="机构、联系人、编号"></label></div><div class="epm-table-wrap"><table class="table"><thead><tr><th>机构与编号</th><th>类别</th><th>联系人</th><th>状态</th><th>合作方向</th><th>项目/资源</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.id)}</small></td><td>${esc(x.type)}</td><td>${esc(x.contact||'—')}</td><td><span class="epm-state">${esc(x.status)}</span></td><td>${esc((x.scope||[]).join('、')||'—')}</td><td>${(x.projects||[]).length} / ${(x.resources||[]).length}</td><td><button class="btn sm secondary" onclick="epmDetail('${esc(x.id)}')">资料与授权</button><button class="btn sm" style="margin-left:6px" onclick="epmWorkbench('${esc(x.id)}')">项目与审核</button></td></tr>`).join('')||'<tr><td colspan="7">暂无符合条件的合作伙伴</td></tr>'}</tbody></table></div></div><div class="notice">当前为离线演示：仅同一浏览器中可共享合作伙伴台账；官网展示名单须单独审核并获得展示授权，不能把示例名称当作真实合作关系。</div></section>`;
 host.querySelector('#epmType').onchange=e=>{ecosystemTypeFilter=e.target.value;renderEcosystemPartners()};host.querySelector('#epmStatus').onchange=e=>{ecosystemStatusFilter=e.target.value;renderEcosystemPartners()};host.querySelector('#epmSearch').oninput=e=>{ecosystemText=e.target.value;renderEcosystemPartners();host.querySelector('#epmSearch')?.focus()};
}
window.epmNew=()=>{if(!isHQ())return;const name=prompt('合作伙伴机构名称（请勿输入未经授权的真实合作关系）');if(!name?.trim())return;const api=window.MVERI_PARTNER_REGISTRY;const x={id:'EP-'+Date.now(),name:name.trim(),type:'其他',contact:'',status:'待审核',account:'',password:'',scope:[],projects:[],resources:[],created:new Date().toISOString().slice(0,10)};api.audit(x,'总部新建','待审核');renderEcosystemPartners()};
window.epmDetail=id=>{if(!isHQ())return;const api=window.MVERI_PARTNER_REGISTRY,x=api.find(id);if(!x)return;let host=document.getElementById('view');host.innerHTML=`<div class="epm"><button class="btn secondary" onclick="renderEcosystemPartners()">← 返回合作伙伴目录</button><div class="intro"><div><h2>${esc(x.name)}</h2><p class="muted">${esc(x.id)} · ${esc(x.type)} · ${esc(x.status)}</p></div></div><div class="grid2"><div class="panel"><h3>机构资料与授权</h3><form id="epmEdit"><label class="field">机构名称<input name="name" required value="${esc(x.name)}"></label><label class="field">伙伴类型<select name="type">${['科技企业','职业院校','央企','教育科技','培训机构','行业组织','其他'].map(t=>`<option ${x.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">联系人<input name="contact" value="${esc(x.contact||'')}"></label><label class="field">联系电话<input name="phone" value="${esc(x.phone||'')}"></label><label class="field">合作方向<input name="scope" value="${esc((x.scope||[]).join('、'))}" placeholder="课程资源、培训服务、技术支持"></label><label class="field">入驻状态<select name="status">${['待审核','已通过','已驳回','已停用'].map(t=>`<option ${x.status===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">登录账号<input name="account" value="${esc(x.account||'')}"></label><label class="field">演示密码<input name="password" type="password" value="${esc(x.password||'')}" placeholder="只用于离线演示"></label><button class="btn" type="submit">保存并记录操作日志</button></form></div><div class="panel"><h3>协作业务</h3><p>项目 ${(x.projects||[]).length} 项 · 资源 ${(x.resources||[]).length} 条</p><h4>合作项目</h4>${(x.projects||[]).map(p=>`<div class="epm-line">${esc(p.name)} · ${esc(p.stage)}</div>`).join('')||'<p class="muted">暂无项目</p>'}<h4>资源提交</h4>${(x.resources||[]).map(r=>`<div class="epm-line">${esc(r.title)} · ${esc(r.status)} ${r.status==='待审核'?`<button class="btn sm secondary" data-approve-resource="${esc(r.id)}">审核通过</button>`:''}</div>`).join('')||'<p class="muted">暂无资源</p>'}<button class="btn secondary" id="epmProjectAdd">＋ 创建协作项目</button><h4>操作记录</h4>${(x.history||[]).map(h=>`<div class="epm-line"><small>${esc(h.time)} · ${esc(h.action)} · ${esc(h.note)}</small></div>`).join('')||'<p class="muted">暂无记录</p>'}</div></div></div>`;
 host.querySelector('#epmEdit').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),a=api.get();if(d.get('account')&&a.some(y=>y.id!==id&&y.account===d.get('account')))return alert('此登录账号已占用');['name','type','contact','phone','status','account','password'].forEach(k=>x[k]=String(d.get(k)||'').trim());x.scope=String(d.get('scope')||'').split(/[、,，]/).map(s=>s.trim()).filter(Boolean);api.audit(x,'总部资料与授权更新',x.status);renderEcosystemPartners()};host.querySelector('#epmProjectAdd').onclick=()=>{const name=prompt('新协作项目名称');if(!name?.trim())return;x.projects=x.projects||[];x.projects.push({id:'PR-'+Date.now(),name:name.trim(),stage:'筹备中',note:''});api.audit(x,'总部创建协作项目',name);window.epmDetail(id)};host.querySelectorAll('[data-approve-resource]').forEach(b=>b.onclick=()=>{const r=(x.resources||[]).find(r=>r.id===b.dataset.approveResource);if(!r)return;r.status='已通过';api.audit(x,'资源审核通过',r.title);window.epmDetail(id)});
};


/* V72.38: partner operations console layered on top of V72.37 registry and authorization form. */
window.epmWorkbench=function(id){
 if(!isHQ())return;const api=window.MVERI_PARTNER_REGISTRY,p=api?.find(id);if(!p)return;
 const host=document.getElementById('view');if(!host)return;
 const items=p.projects||[],resources=p.resources||[],logs=p.history||[];
 const stat=s=>`<span class="epm-state">${esc(s||'待处理')}</span>`;
 host.innerHTML=`<section class="epm epm38"><div class="intro"><div><button class="btn secondary" id="epmBack">← 返回合作伙伴列表</button><h2 style="margin-top:18px">${esc(p.name)} · 合作协作中心</h2><p class="muted">项目协同、任务反馈、资源审核、资质授权和过程追溯 ｜ ${esc(p.id)}</p></div><button class="btn" id="epmGoAuth">机构资料与授权 →</button></div>
 <div class="cards"><div class="metric"><small>合作状态</small><div class="value" style="font-size:20px">${esc(p.status)}</div></div><div class="metric"><small>合作项目</small><div class="value">${items.length}</div></div><div class="metric"><small>待审核资源</small><div class="value">${resources.filter(x=>x.status==='待审核').length}</div></div><div class="metric"><small>操作记录</small><div class="value">${logs.length}</div></div></div>
 <div class="grid2"><section class="panel"><h3>合作项目与任务配置</h3><p class="muted">创建项目，设置牵头部门与里程碑；合作伙伴可在专属工作台提交进度。</p><form id="epm38Project" class="epm38-form"><label>项目名称<input required name="name" maxlength="100" placeholder="如：职业能力课程资源共建"></label><label>项目类型<select name="type"><option>能力培训</option><option>能力测评</option><option>能力认证</option><option>标准研究</option><option>区域协同</option><option>资源共建</option></select></label><label>牵头单位<input name="owner" maxlength="80" value="研究院总部"></label><label>计划完成日期<input type="date" name="end"></label><label class="epm38-wide">项目目标与协作事项<textarea name="description" rows="3" maxlength="600" placeholder="明确项目目标、伙伴任务及交付要求"></textarea></label><label class="epm38-wide">里程碑（每行一项）<textarea name="milestones" rows="3" maxlength="500" placeholder="任务立项\n资源提交\n成果验收"></textarea></label><button class="btn" type="submit">＋ 创建合作项目</button></form><h4>项目执行台账</h4>${items.length?items.map(x=>`<article class="epm38-item"><div><strong>${esc(x.name)}</strong> ${stat(x.stage)}<p class="muted">${esc(x.type||'合作项目')} · ${esc(x.owner||'总部牵头')} · 计划 ${esc(x.end||'待定')}</p><p>${esc(x.note||'暂无最新反馈')}</p><small>伙伴反馈记录 ${(x.feedback||[]).length} 条；里程碑 ${(x.milestones||[]).length} 项</small></div><div><select aria-label="调整项目阶段" data-stage="${esc(x.id)}">${['筹备中','执行中','待总部验收','已验收','已完成','已暂停'].map(s=>`<option ${x.stage===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn sm secondary" data-milestone="${esc(x.id)}">增加里程碑</button></div></article>`).join(''):'<p class="muted">暂无合作项目</p>'}</section>
 <section class="panel"><h3>资源审核工作台</h3><p class="muted">审核资源内容、给出退回说明；未审核的资料不得自动发布到官网。</p>${resources.length?resources.map(r=>`<article class="epm38-item"><div><strong>${esc(r.title)}</strong> ${stat(r.status)}<p class="muted">${esc(r.kind||'资源')} · ${esc(r.service||'能力发展')} · ${esc(r.sharing||'需授权共享')}</p><p>${esc(r.note||'')}</p>${r.reviewNote?`<small>总部审核意见：${esc(r.reviewNote)}</small>`:''}</div><div><button class="btn sm secondary" data-review="${esc(r.id)}" data-status="已通过">审核通过</button><button class="btn sm secondary" data-review="${esc(r.id)}" data-status="需修改">退回修改</button><button class="btn sm secondary" data-review="${esc(r.id)}" data-status="已驳回">驳回</button></div></article>`).join(''):'<p class="muted">暂无待审核资源</p>'}<h3>合作运营信息</h3><form id="epm38Contract"><label class="field">合作授权截止<input type="date" name="expires" value="${esc(p.expires||'')}"></label><label class="field">合作协议或审核备注<textarea name="agreementNote" rows="3" maxlength="700">${esc(p.agreementNote||'')}</textarea></label><button class="btn secondary">保存运营信息</button></form><h3>最近操作与审核记录</h3>${logs.slice(0,16).map(x=>`<div class="epm-line"><b>${esc(x.action)}</b> · ${esc(x.note)}<br><small>${esc(x.time)}</small></div>`).join('')||'<p class="muted">暂无操作记录</p>'}</section></div></section>`;
 host.querySelector('#epmBack').onclick=()=>renderEcosystemPartners();host.querySelector('#epmGoAuth').onclick=()=>window.epmDetail(id);
 host.querySelector('#epm38Project').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),name=String(d.get('name')||'').trim();if(!name)return;const ms=String(d.get('milestones')||'').split(/\n/).map(s=>s.trim()).filter(Boolean);p.projects=p.projects||[];p.projects.unshift({id:'PR-'+Date.now(),name,type:String(d.get('type')||''),owner:String(d.get('owner')||''),end:String(d.get('end')||''),description:String(d.get('description')||''),stage:'筹备中',note:'',feedback:[],milestones:ms.map((m,i)=>({id:'MS-'+i+'-'+Date.now(),name:m,status:'待处理',date:''}))});api.audit(p,'总部创建合作项目',name);window.epmWorkbench(id)};
 host.querySelector('#epm38Contract').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);p.expires=String(d.get('expires')||'');p.agreementNote=String(d.get('agreementNote')||'').slice(0,700);api.audit(p,'总部更新合作运营信息',p.expires||'未设置期限');window.epmWorkbench(id)};
 host.querySelectorAll('[data-stage]').forEach(s=>s.onchange=()=>{const x=(p.projects||[]).find(z=>z.id===s.dataset.stage);if(!x)return;x.stage=s.value;api.audit(p,'总部调整项目状态',x.name+' → '+x.stage);window.epmWorkbench(id)});
 host.querySelectorAll('[data-milestone]').forEach(b=>b.onclick=()=>{const x=(p.projects||[]).find(z=>z.id===b.dataset.milestone);if(!x)return;const m=prompt('请输入新增里程碑名称');if(!m?.trim())return;x.milestones=x.milestones||[];x.milestones.push({id:'MS-'+Date.now(),name:m.trim().slice(0,100),status:'待处理'});api.audit(p,'总部追加项目里程碑',x.name+' / '+m);window.epmWorkbench(id)});
 host.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const r=(p.resources||[]).find(z=>z.id===b.dataset.review);if(!r)return;let note='';if(b.dataset.status!=='已通过'){const val=prompt('请填写审核反馈意见（将显示给合作伙伴）');if(val===null||!val.trim())return;note=val.trim().slice(0,500)}else note='已通过本机演示审核，公开发布仍需另行授权';r.status=b.dataset.status;r.reviewNote=note;r.reviewedAt=new Date().toLocaleString('zh-CN');api.audit(p,'总部资源审核',r.title+' → '+r.status);window.epmWorkbench(id)});
};

const renderBeforePermissions=render;render=function(p){if(p==='ecosystem-partners')return renderEcosystemPartners();if(p==='permissions')return renderPermissions();return renderBeforePermissions(p)};
initV2();if(!role||route()==='index')login();else frame();


// V62: use native multi-page navigation. Each menu item resolves to its own HTML page.
// Accordion expansion state is preserved by setupNavAccordion via sessionStorage.
// Avoid intercepting anchors and re-rendering an incompatible page in the old shell.
